\caption{Deterministic algorithm for $O(\Delta)$ edge coloring for (adversarial) one sided vertex arrival bipartite streams, using $\widetilde{O}(n)$ bits of advice }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of vertex arrivals for $n$-vertex graph $G=(A \sqcup B,E)$ of max degree $\Delta$
      \Statex
      \Statex $\delta \in (0,1)$ is a parameter so that, if the advice is chosen randomly, it will work for all inputs with probability $\ge 1 - \delta$
      \Statex
      \Statex \underline{\textbf{Initialize}:}
      \Statex Let $C = 2^{18} \Delta$. 
      \Statex Let $s = \ceil{2^{18} \log\frac{n \Delta}{\delta}} $.
      \Statex Advice: $(\sigma_v)_{v \in B}$, where each $\sigma_v$ is a permutation over $[C]$. If chosen randomly, each is $(\epsilon,s)$-wise independent for $\epsilon \le C^{-s - 1}$

      \For{$v \in B$}
        \State $b_v \gets 1$.
        \State $Q_v \gets [s]$.
      \EndFor

    \Statex \underline{\textbf{Process}(vertex $x$ with multiset $M_x$ of edges to $B$)}
      \Statex Let $d_{x,y}$ be the number of times edge $\{x,y\}$ is in $M_x$
      \For{each $y \in B$ with $d_{x,y} > 0$}
        \If{$d_{x,y} < \frac{1}{16} s$}
          \State Let $F_y = (b_y -1) s + Q_y$ \Else
          \State Let $F_y = ((b_y -1) s + Q_y) \sqcup [b_y s, b_y + \ceil{\frac{64 d_{a,b}}{s}} s]$ \EndIf
      \EndFor
      \State Construct bipartite graph $H$ from $M_x$ to $[C]$, edge $e \in M_x$
      is linked to all $c \in \sigma_y[F_y]$. \State Compute an $M_x$-saturating matching $P$ of $H$. \For{each $e \in M_x$}
        \State Assign color $P(e)$ to $e$
        \If{$d_{x,y} < \frac{1}{16} s$}
          \State Remove $\sigma_y^{-1} - (b_y - 1)s$ from $Q_y$
        \EndIf
      \EndFor
      \For{each $y \in B$ with $d_{x,y} > 0$}
        \If{$d_{x,y} < \frac{1}{16} s$}
          \If{$|Q_y| \le s - \frac{1}{2^{17}} s$}
            \State $b_y \gets b_y + 1$ \State $Q_y \gets [s]$
          \EndIf
        \Else
          \State $Q_y \gets [s]$
          \State $b_y \gets b_y + \ceil{\frac{2 d_{x,y}}{s}} + 1$ \EndIf
      \EndFor

    \end{algorithmic}

The W-streaming edge-arrival algorithm is given by \Cref{alg:va-to-ea-conversion}. The algorithm uses $s = O(\sqrt{\Delta})$ instances of $\mathcal{A}$. This algorithm maintains a pool $P$ of edges, and whenever it receives a new edge it adds it to the pool. Edges with high multiplicity ($\widetilde{\Omega}(\sqrt{\Delta}/\log(n^2/\delta))$ in $P$ are moved to a different pool $L$; since there are not many of this type, they can be stored using only $\widetilde{O}(n\sqrt{\Delta})$ space. When a vertex $v$ reaches a high degree ($\ge\sqrt{\Delta}$) in the pool, it and its incident edges are removed from $P$ and assigned to a random instance of $\mathcal{A}$ which has not yet received $v$. At the end of the stream, all edges still stored in either $P$ or $L$ are colored.

  \begin{algorithm}[htb!]
    \caption{W-streaming algorithm for $O(\Delta)$ edge coloring on edge-arrival stream given black-box access to algorithm $\mathcal{A}$ for $C \Delta$ edge coloring on vertex-arrival stream }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of edge arrivals for $n$-vertex graph $G=(A \sqcup B,E)$
      \Statex
      \Statex \underline{\textbf{Initialize}:}
      \State Let $s = 2 \ceil{\sqrt{\Delta}}$ 
      \State Let $\tau = \floor{\frac{\sqrt{\Delta}}{9 \ln(n/\delta)}}$ 

      \State $P \gets \emptyset$ is a multiset of edges -- used to cache all arriving edges
      \State $L \gets \emptyset$ is a multiset of edges -- used to efficiently store certain edge types which have high multiplicity 

      \For{$i \in [s]$}
        \State $\mathcal{I}^{(i)} \gets$ instance of algorithm $\mathcal{A}$ for graphs of max degree $\ceil{4 \Delta / s}$; this will use $C \ceil{4 \Delta / s}$ colors
        \State $x^{(i)} \gets [0,\ldots,0] \in \{0,1\}^A$, tracks for which vertices $w$ in $A$ the instance $\mathcal{I}^{(i)}$ has received $(w,M_w)$
      \EndFor

    \Statex \underline{\textbf{Process}(edge $\{x,y\}$)}
      \State $P \gets P \cup \{\{x,y\}\}$.

      \If{edge $\{x,y\}$ has multiplicity > $\tau$ in $P$}
        \State Remove all copies of $\{x,y\}$ from $P$, and add them to $L$ \State \textbf{return}
      \EndIf

      \If{$\exists v \in A$ with degree $\ge \ceil{\sqrt{\Delta}}$ in $P$}
          \State Pick random $i$ from $\{ j \in [s]: x^{(j)}_v = 0\}$ \State $x^{(i)}_v \gets 1$
          \State Let $M_v$ be edges incident on $v$ in $P$
          \State Send $(v,M_v)$ to $\mathcal{I}^{(i)}$ to be colored \State Remove $M_v$ from $P$
      \EndIf

    \Statex \underline{\textbf{End of Stream}}
      \State Color edges in $P \cup L$ greedily using an independent set of $2\Delta - 1$ colors
    \end{algorithmic}
  \end{algorithm}

  \Cref{alg:va-to-ea-conversion} requires $s f(n)$ bits of space to store the instances $\mathcal{I}^{(1)},\ldots,\mathcal{I}^{(s)}$, and $s n$ bits to keep track of the vectors $x^{(1)},\ldots,x^{(s)}$. Since the edges adjacent to a vertex in $A$ are removed from $P$ as soon as it reaches degree $\ceil{\sqrt{\Delta}}$, the total number of edges in $P$, counting multiplicity, will be $\le |A| (\ceil{\sqrt{\Delta}} - 1) = O(n\sqrt{\Delta})$. Thus, $P$ can be stored using $O(n \sqrt{\Delta} \log(n^2 / \delta))$ bits of space. Finally, since $L$ receives only edges whose multiplicity was at least $\sqrt{\Delta} / \log n$, it will contain at most $(n \Delta / 2) / (\sqrt{\Delta} / \log n) = n \sqrt{\Delta} / (2 \log n)$ distinct edges; keeping track of them and their multiplicity can be done in $O(n \sqrt{\Delta} \log (n \Delta) / \log n)$ space. In total, \Cref{alg:va-to-ea-conversion}  will require $O(\sqrt{\Delta} (f(n) + n (\log (n \Delta)) \log(n/\delta)))$ bits of space in total.

  The total number of colors used is $2 \ceil{\sqrt{\Delta}} \cdot C \ceil{4 \Delta / s} + (2 \Delta - 1) = O(\Delta)$.

  Because \Cref{alg:va-to-ea-conversion} only sends a star around a vertex $v$ to an instance $\mathcal{I}^{(i)}$ (Line \ref{step:va-to-ea-conversion-send-to-va}) when the vertex $v$ has degree $= \ceil{\sqrt{\Delta}}$ in $P$, the maximum degree of arriving vertices that any instance of $\mathcal{A}$ will process will be $\ceil{\sqrt{\Delta}}$. However, it is still possible that for some sketch $\mathcal{I}^{(i)}$, a vertex $v \in B$ will receive a too many edges from vertices in $A$ that the sketch $\mathcal{I}^{(i)}$ receives later.

  For some pair $i \in [s]$, $z \in B$, we will show that sketch $\mathcal{I}^{(i)}$ receives $\le 4 \Delta / s$ edges (counting multiplicity) for $z$, with $\ge \frac{\delta}{n^2}$ probability. Let $X_1,\ldots,X_\Delta$ be random variables, where $X_i$ is the number of edges that are sent to $\mathcal{I}^{(i)}$ when the $j$th star adjacent to $z$ is removed. If the stream ends before an $j$th star is removed, then $X_j = 0$. Because Line \ref{step:va-to-ea-conversion-hide-highmult} removes all edges with multiplicity $> \tau$ in $P$, $z$ will have at most $\tau$ edges between it and the center of the $j$th star, so $X_j \le \tau$. Furthermore, at the time the $j$th star is selected, the algorithm makes a random decision on Line \ref{step:va-to-ea-conversion-pick-star} to choose which sketch will receive it. Because $s = 2\ceil{\sqrt{\Delta}}$, and each star has root degree only $\ceil{\sqrt{\Delta}}$, there will always be $\ge s/2$ instances that have not received a given vertex as the root of a star, so the probability that $\mathcal{I}^{(i)}$ will receive the $j$th star is $\le \frac{2}{s}$. Thus $\mathbb{E}[X_j | X_1,\ldots,X_{j-1}] \le 2 \tau / s$. This bound holds even if the input stream is produced by an adaptive adversary. Since the degree of $z$ will be less than $\le \Delta$ at the end of the stream, we also have $\mathbb{E}[\sum_{j \in \Delta} X_j] \le 2 \Delta / s$.

  We now apply the multiplicative (Chernoff-like) form of Azuma's inequality, on the $[0,1]$ random variables $Y_1,\ldots,Y_\Delta$, defined by $Y_j := X_j / \tau$. Let $\alpha = \mathbb{E}[\sum_{j \in \Delta} Y_j]$.
  \begin{align*}
    \Pr\left[\sum_{i \in [\Delta]} X_j \ge 4 \Delta / s\right] &= \Pr\left[ \sum_{i \in [\Delta]} Y_j \ge \frac{4 \Delta}{s \tau} \right] = \Pr\left[ \sum_{i \in [\Delta]} Y_j \ge \left(1 + \left(\frac{4 \Delta}{s \tau \alpha} - 1\right)\right) \alpha \right] \\
      &\le \exp\left( - \frac{1}{3} \left(\frac{4 \Delta}{s \tau \alpha} - 1\right) \cdot \alpha \right) \qquad\qquad \text{since $\frac{4 \Delta}{s \tau \alpha} - 1 > 1$} \\
      &\le \exp\left( - \frac{1}{3} \frac{2 \Delta}{s \tau \alpha}\cdot \alpha \right) =  \exp\left( - \frac{2}{3} \frac{\Delta}{s \tau} \right) \\
      &= \exp\left( - \frac{2 \Delta}{3 \cdot 2 \ceil{\sqrt{\Delta}} \floor{\sqrt{\Delta} / (9 \ln(n/\delta))}} \right) \\
      &\le \exp\left( - 2 \ln(n/\delta)\right) \le \frac{\delta}{n^2} \qquad\qquad \text{since $2 \ceil{\sqrt{\Delta}} \le 3 \sqrt{\Delta}$ and $1/\floor{x} \ge 1/x$}
  \end{align*}

  By a union bound over all $\le n$ vertices $v \in B$, and all $\le n$ instances in $\{\mathcal{I}^{(j)}\}_{j\in [s]}$, we have that the total probability of any vertex $v$ in an instance $\mathcal{I}^{(i)}$ receiving more than $4 \Delta / s$ edges is $\le \delta$.

\caption{W-streaming algorithm for $O(\Delta)$ edge coloring on edge-arrival stream given black-box access to algorithm $\mathcal{A}$ for $C \Delta$ edge coloring on vertex-arrival stream }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of edge arrivals for $n$-vertex graph $G=(A \sqcup B,E)$
      \Statex
      \Statex \underline{\textbf{Initialize}:}
      \State Let $s = 2 \ceil{\sqrt{\Delta}}$ 
      \State Let $\tau = \floor{\frac{\sqrt{\Delta}}{9 \ln(n/\delta)}}$ 

      \State $P \gets \emptyset$ is a multiset of edges -- used to cache all arriving edges
      \State $L \gets \emptyset$ is a multiset of edges -- used to efficiently store certain edge types which have high multiplicity 

      \For{$i \in [s]$}
        \State $\mathcal{I}^{(i)} \gets$ instance of algorithm $\mathcal{A}$ for graphs of max degree $\ceil{4 \Delta / s}$; this will use $C \ceil{4 \Delta / s}$ colors
        \State $x^{(i)} \gets [0,\ldots,0] \in \{0,1\}^A$, tracks for which vertices $w$ in $A$ the instance $\mathcal{I}^{(i)}$ has received $(w,M_w)$
      \EndFor

    \Statex \underline{\textbf{Process}(edge $\{x,y\}$)}
      \State $P \gets P \cup \{\{x,y\}\}$.

      \If{edge $\{x,y\}$ has multiplicity > $\tau$ in $P$}
        \State Remove all copies of $\{x,y\}$ from $P$, and add them to $L$ \State \textbf{return}
      \EndIf

      \If{$\exists v \in A$ with degree $\ge \ceil{\sqrt{\Delta}}$ in $P$}
          \State Pick random $i$ from $\{ j \in [s]: x^{(j)}_v = 0\}$ \State $x^{(i)}_v \gets 1$
          \State Let $M_v$ be edges incident on $v$ in $P$
          \State Send $(v,M_v)$ to $\mathcal{I}^{(i)}$ to be colored \State Remove $M_v$ from $P$
      \EndIf

    \Statex \underline{\textbf{End of Stream}}
      \State Color edges in $P \cup L$ greedily using an independent set of $2\Delta - 1$ colors
    \end{algorithmic}

\caption{Storing free regions from a permutation }
  \begin{algorithmic}[1]
    \Statex \underline{$F \gets $\textbf{InitFreeTracker}($C$,$s$,$\Delta$,$\sigma$\textbf{):}} \Comment{Assume $C$,$s$,$\Delta$ are powers of two, and $\sigma$ permutation of $[C]$, and $C \ge \Delta$}
    \State $H \gets [s]$ be a subset of $[s]$
    \State $b \gets 1$ be a counter between $1$ and $C/s$

    \State \textcolor{PineGreen}{Optional: $Q \gets \emptyset$ is a set of references to objects}


    \Statex

    \Statex \underline{\textbf{Interpreting $F$ as subset of $[C]$}}
    \State \textbf{return} $\sigma[H + (b -1) s]$
    \Statex


    \Statex \underline{$F$\textbf{.RemoveAndUpdate(}$c$, \textcolor{PineGreen}{optional: $o$}\textbf{)}} \Comment{Requires $c \in F_v$}
    \State $H \gets H \setminus \{ \sigma^{-1}(c)  \}$
    \State \textcolor{PineGreen}{Optional: Add a reference to $o$, and store it in $Q$}
    \If{$|H| \le s - s\Delta /C$} \Comment{Switch to next block}
      \State $H \gets [s]$
      \State $b \gets b + 1$
      \State \textcolor{PineGreen}{Optional: Drop all references in $Q$ and set $Q \gets \emptyset$}
    \EndIf
  \end{algorithmic}

We will show that \Cref{alg:rand-ea-edgecol} satisfies the claims of the lemma, if $\Delta = \Omega(\log (n/\delta))$. (For smaller values of $\Delta$, fall back to \Cref{alg:simple-greedy}.) In the following argument, we shall assume that the permutations $(\sigma_v)_{v\in S}$ are $s$-wise independent. The pseudocode states $(\epsilon,s)$-wise independence, since that is attainable per \Cref{lem:fast-permutations} using only $O(s \mathrm{poly}(\log 1/\epsilon, \log s))$ bits of randomness per permutation. This will not affect the validity of the proof, since it at most increases the probabilities of events $H_{\{u,v\}}$ and $J_{u,v}$ defined later by $\epsilon$, which is polynomially smaller than the losses in the argument due to bounding the number of events by $n^2$ instead of $\binom{n}{2}$ or $n^2 - n$. We also assume that $\Delta$ is a power of two; if not, we can increase $\Delta$ to the nearest power of two, and the algorithm will still give an $O(\Delta)$ coloring.

  Each color tracker $F_v$ can be stored using $O(\log \Delta)$ bits for $b$, and $O(s)$ bits for $H$; thus 
  \Cref{alg:rand-ea-edgecol}  will use $O(n (s + \log \Delta)) = O(n \sqrt{\Delta \log (n/\delta)})$ bits in total.
  For $\Delta = O(\log (n/\delta))$, the \Cref{alg:simple-greedy} uses $O(n \Delta)$ bits, which is also $O(n \sqrt{\Delta \log (n/\delta)})$.


  \begin{algorithm}[htb!]
    \caption{Randomized algorithm for $O(\Delta)$ edge coloring for simple graph edge arrival streams }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of vertex arrivals $n$-vertex graph $G=(A \sqcup B, E)$
    \Statex Assume $\Delta$ is a power of two, and $\Delta = \Omega(\log(n/\delta))$
      \Statex
      \Statex \underline{\textbf{Initialize}:}
      \State Let $C = 128 \Delta$
      \State Let $s$ be the least power of two which is $\ge 128 \sqrt{\Delta \log (n/\delta)}$
      \State Let $\mathcal{H}$ be an ($\epsilon,s$)-wise independent distribution of permutations on $[C]$, with $\epsilon \le \exp(-s^2/C) \le (\delta/n)^{128}$

      \For{$v \in B$}
        \State Let $\sigma_v$ be a random permutation from $\mathcal{H}$
        \State $F_v \gets \textsc{InitFreeTracker}(C, s, \Delta, \sigma_v)$, without reference count tracking
      \EndFor
    \Statex 

    \Statex 
    \Statex\underline{\textbf{Process}(edge $\{x,y\}$) $\rightarrow$ \textbf{color}}
      \If{$F_x \cap F_y = \emptyset$}
        \State abort
      \EndIf

      \State Let $c$ be chosen uniformly at random from $F_x \cap F_y$. \State $F_x.\textsc{RemoveAndUpdate(c)}$
      \State $F_y.\textsc{RemoveAndUpdate(c)}$
      \State \textbf{return} color $c$
    \end{algorithmic}
  \end{algorithm}

  For each $v \in V$, $i \in [C/s]$, write $P_{v,i}$ for the set $\sigma[[s] + (i -1) s]$ of the free region tracker $F_v$ for vertex $v$. (See \Cref{alg:ds-rand-blocks}.) Since we are assuming the $\sigma_v$ are $s$-wise independent, the set $P_{v,i}$ will be uniformly distributed over over $\binom{[C]}{s}$.

  Consider a fixed input stream $e_1,e_2,\ldots$, where the edges of the stream together form the simple graph $G$. Write $b_{x,\{u,v\}}$ for the value of the counter $b$ inside $F_x$ just before the algorithm processed edge $\{u,v\}$. Let $D_{\{u,v\}} := P_{u, b_{u,\{u,v\}}} \cap P_{v, b_{v,\{u,v\}}}$. Also define $M_{u,v} := \{ x : \{x,u\} \in G \land b_{u,\{x,u\}} = b_{u,\{u,v\}} \land \{x,u\} \prec \{u,v\}\}$; this is the set of vertices which were adjacent to $u$, for which the edge $\{x,u\}$ was added before $\{u,v\}$, and while the value of the counter $b$ inside $F_u$ for vertex $u$ was the same as it was at the time $\{u,v\}$ was added. This is the set of vertices whose color
  choices \emph{might} reduce the size of $F_u \cap F_v$ at the time $\{u,v\}$ is added. 

  We will first show that of the following two classes of $m$ events, the probability that any of the events is true is $\le \delta / 2$.
  \begin{align*}
    \forall \{u,v\} \in G: H_{\{u,v\}} & := \left\{ D_{\{u,v\}} \le \frac{1}{2} s^2/C \right\} \\
    \forall (u,v) \text{ where } \{u,v\} \in G: J_{u,v} & := \left\{ \sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}| \ge  2 \cdot \frac{3}{2} \frac{s^3}{C^2} \frac{\Delta s}{C} \right\} \\
  \end{align*}

  To bound the probability of $H_{\{u,v\}}$, we let $X_1,\ldots,X_C$ be indicator random variables where $X_i = 1$ iff $i \in P_{u, b_{u,\{u,v\}}}$.  Since the $X_i$ are negatively associated\cite{JoagDevP83}, the proof of the Chernoff bound holds, and 
  \begin{align*}
    \Pr[ |D_{\{u,v\}}| \le \frac{1}{2} s^2/C ] &= \Pr[ D_{\{u,v\}} \le \frac{1}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &= \Pr[ \sum_{i \in [P_{v, b_{v,\{u,v\}}}]} X_i \le \frac{1}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &\le \exp( - \frac{1}{8} \mathbb{E}[D_{\{u,v\}}])= \exp(- \frac{s^2}{8 C} )  \\
       &\le \exp(- 16 \log\frac{n}{\delta}) \le \frac{\delta}{2 n^2}
  \end{align*}

  To bound the probability of the events $\{J_{u,v}\}$, we will show that $|D_{u,v}|$ is not too large w.h.p, and conditioned on that, the sum $\sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}|$ is not too large w.h.p. With $\{X_i\}_{i\in[C]}$ as defined above:
  \begin{align*}
    \Pr[ |D_{\{u,v\}}| \ge \frac{3}{2} s^2/C ] &= \Pr[ D_{\{u,v\}} \ge \frac{3}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &\le  \Pr[ \sum_{i \in [P_{v, b_{v,\{u,v\}}}]} X_i \ge \frac{3}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &\le \exp( - \frac{1}{10} \mathbb{E}[D_{\{u,v\}}]) = \exp(- \frac{s^2}{10 C} ) \\
       &\le \exp(- \frac{128}{10} \log\frac{n}{\delta})\le \frac{\delta}{4 n^2}
  \end{align*}
  The permutations $\{\sigma_x\}_{x \in M_{u,v}}$ are independent of $\sigma_u$ and $\sigma_v$. For each $x \in M_{u,v}$, let $Y_{1,x},\ldots,Y_{C,x}$ be indicator random variables
  where $Y_{i,x}$ is 1 iff $i \in P_{x, b_{x,\{x,u\}}}$, and zero otherwise. Due to the frequency of free color buffer refreshing, $|M_{u,v}| \le s \Delta / C$; and since $|P_{x, b_{x,\{x,u\}}}| = s$, $\mathbb{E} Y_{i,x} = s/C$. Since the $\{Y_{i,x}\}_{i \in D_{\{u,v\}}, x \in M_{u,v}}$ are negatively associated, we can apply a Chernoff bound. If we assume that $|D_{\{u,v\}}| \le \frac{3 s^2}{2 C}$, then we have:
  \begin{align*}
    \Pr\left[ \sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}| \ge 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C}\right]
      &= \Pr\left[ \sum_{i \in D_{\{u,v\}}, x \in M_{u,v}} Y_{i,x} \ge 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} \right] \\
      &\le \exp\left( - \frac{1}{8} \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} \right) \\
      &\le \exp(- 12 (\log(n/\delta))^2) \le \frac{\delta}{4 n^2}
  \end{align*}
  Thus, the probability that either $|D_{\{u,v\}}| \ge \frac{3 s^2}{2 C}$ or event $J_{u,v}$ does not hold is $\frac{\delta}{2 n^2}$.

  For the rest of the proof, we will consider the case where none of the events $J_{u,v}$ or $H_{\{u,v\}}$ holds; this happens with probability $\ge 1 - \delta/2$. Fix values of the $(\sigma_v)_{v\in V}$ satisfying none of the events. The only other random decisions made
  by the algorithm are the choices made on Line \ref{step:rand-ea-edgecol-pick-color}, randomly choosing the edge color $\chi_{\{u,v\}}$ for $\{u,v\}$ from $F_u \cap F_v$. We will prove by induction on
  the number of edges processed that the probability of $|F_u \cap F_v| \le \frac{1}{4} s^2 / C$ holding at the time Line \ref{step:rand-ea-edgecol-pick-color} is executed, in total over all $t$ edges so far is, $\le \delta \cdot t / (2n^2)$.

  To do this, we will use the following lower bound:
  \begin{align}
    |F_u \cap F_v| \ge |D_{\{u,v\}}| - \sum_{x \in M_{u,v}} W_{x,u} - \sum_{x \in M_{u,v}} W_{x,v} \end{align}
  Here $W_{x,u}$ is the indicator random variable for the event that the color chosen for
  $\{x,u\}$ was in $D_{\{u,v\}}$. The lower bound overcounts the number of colors in $D_{\{u,v\}}$ that have been removed from $F_u \cap F_v$.

  The base case of the induction (0 edges) is immediate. Assume that we are processing
  edge $\{u,v\}$, and that all edges $\{x,y\}$ earlier in the stream, when they were processed,
  had $|F_x \cap F_y| \ge \frac{s^2}{4 C}$. For each $x \in M_{u,v}$, the color $\chi_{\{x,u\}}$ was drawn uniformly at random from \emph{some} set $F_x \cap F_u$, which we assume satisfies $|F_x \cap F_u| \ge \frac{s^2}{4 C}$. For any subset $H$ of $D_{\{x,u\}}$ of size $\frac{s^2}{4 C}$, if $\hat{\chi}$ is chosen u.a.r. from $H$, then 
  \begin{align*}
    \Pr[\hat{\chi} \in D_{\{u,v\}}] \le \frac{|H \cap D_{\{u,v\}}|}{|H|} \le \frac{4 C}{s^2} |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}|
  \end{align*}
  Conditioned on the color choices of all earlier edges, we thus have $\mathbb{E} W_{x,u} \le \frac{4 C}{s^2} |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}|$. Thus
  \begin{align*}
    \mathbb{E}\left[\sum_{x \in M_{u,v}} W_{x,u} + \sum_{x \in M_{v,u}} W_{x,v}\right] &\le \frac{4 C}{s^2} \left(\sum_{x \in M_{u,v}}  |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}| + \sum_{x \in M_{v,u}}  |P_{x,b_{x,\{x,v\}}} \cap D_{\{u,v\}}| \right) \\
      &\le \frac{4 C}{s^2} \cdot 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} = 12 \frac{\Delta}{C} \frac{s^2}{C} < \frac{s^2}{8 C} & \text{since $\Delta \le C / 128$}
  \end{align*}

  By the multiplicative/Chernoff-like formulation of Azuma's inequality,
  \begin{align*}
    \Pr&\left[\sum_{x \in M_{u,v}} W_{x,u} + \sum_{x \in M_{v,u}} W_{x,v} \ge \frac{s^2}{4 C}\right] \\
      &\le \exp( -\frac{1}{3} \frac{s^2}{4 C}) \le \exp\left( - \frac{32}{3} \log\frac{n}{\delta} \right) \le \frac{\delta}{2 n^2}
  \end{align*}
  By a union bound over all edges, the probability that any edge $\{u,v\}$ has $|F_u \cap F_v| \le \frac{s^2}{4 C}$ is $\le \delta / 2$.

  We have shown that, in total, the probability of the algorithm aborting because
  $F_u \cap F_v = \emptyset$ is $\le \delta$.

We will prove this in two steps. First, define a specific property U 
  that the $(\sigma_v)_{v\in V}$ should satisfy with probability $\ge 1 - \delta$; second, prove that if this property holds, then any graph $H$ can be colored.

  The permutations $(\sigma_v)_{v\in V}$ satisfy property U if:
  \begin{itemize}
    \item For all pairs $(u,i),(v,j) \in V \times [C/s]$, with $u \ne v$, we have $|P_{u,i} \cap P_{v,i}| \ge \frac{s^2}{2 C}$.
    \item For each $(u,i) \in V \times [C/s]$, $S \subseteq (V \setminus \{s\}) \times [C/s]$ where $|S| \le s \Delta / C$ and $S$ includes no two vertices $(v,i),(u,j)$ with $v = u$, and all $T \in \binom{P_{u,i}}{|S| - 1}$, there exists some $(x,j) \in S$ for which $|P_{x,j} \cap T| < \frac{1}{10} |P_{x,j} \cap P_{u,i}|$. (This is, in effect, a stronger version of Hall's condition).
  \end{itemize}

  For the first part of property $U$, it is straightforward to bound the probability that it does not hold. For a given pair $(u,i),(v,j) \in V \times [C/s]$, $u\ne v$, because the permutations are $(\epsilon,s)$-wise independent, the sets $P_{u,i}$ and $P_{v,j}$ are within $\epsilon$-total-variation distance of being uniformly random subsets of $[C]$ of size $s$, we can apply a Chernoff bound for the number of elements in $P_{u,i}$ that lie in $P_{v,j}$:
  \begin{align}
    \Pr[ P_{u,i} \cap P_{v,j} \le \frac{1}{2} \frac{s^2}{C} ] \le \exp( -\frac{1}{8}  \frac{s^2}{C} ) + \epsilon \le \exp( - 2^{10} \log (n/\delta)) + \epsilon \le \frac{\delta}{2 n^2} \end{align}
  (The additive factor $\epsilon$ accounts for the maximum difference in probabilities for this event between the case where $P_{u,i}$ is exactly uniform and the case where it is $\epsilon$-far from such.)

  For the second part, consider a specific combination $(u,i,S,T)$, and fix $P_{u,i}$. Then the probability that this combination violates property U is:
  \begin{align}
    \Pr\left[ \bigwedge_{(x,j) \in S} \left\{ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i}\right\} \right] \le \prod_{(x,j) \in S} \Pr_{P_{x,j}}\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} | \right] \end{align}
  since the $P_{x,j} \in S$ are all independent, since $S$ contains at most one entry for each $v \in V$. Since $P_{x,j}$ is a uniformly random subset $[C]$,
  $P_{x,j} \cap P_{u,i}$ is symmetrically distributed over $P_{u,i}$. Now let $\hat{T}$ be a uniformly random element of $\binom{P_{u,i}}{s}$, and define indicator random variables $\{Y_k\}_{k \in P_{u,i}}$ so that $Y_k = 1$ iff $k \in \hat{T}$; these are negatively associated and $\mathbb{E}[Y_k] = \frac{|S| - 1}{s}$. Thus, if we assume $|P_{x,j} \cap P_{u,i}| = h$:
  \begin{align*}
    \Pr_{P_{x,j}}&\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} |  \Big| |P_{x,j} \cap P_{u,i}| = h\right] \\
      &\le \Pr_{\hat{T}}\left[ |P_{x,j} \cap \hat{T}| \ge \frac{1}{10} h \Big| |P_{x,j} \cap P_{u,i}| = h \right] + \epsilon \\
      &= \Pr_{\{Y_k\}_{k \in P_{u,i}}}\left[ \sum_{k \in P_{u,i}} Y_k \ge \frac{1}{10} h \Big| |P_{x,j} \cap P_{u,i}| = h | \right] + \epsilon \\
      &\le \exp\left( -2 \left(\frac{1}{10} - \frac{|S| - 1}{s} \right)^2 h \right) + \epsilon \\
      &\le \exp\left( -2 \left(\frac{1}{10} - \frac{\Delta}{C} \right)^2 h \right) + \epsilon \le \exp\left( - h / 200 \right) + \epsilon  \qquad \text{since $C = 32 \Delta$}
  \end{align*}
  This bound is useful only if $h$ is large enough. By the law of total probability, and using the bound from Eq. \ref{eq:puv-size-lb} to handle the case where $h$ is small:
  \begin{align*}
    \Pr_{P_{x,j}}&\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} | \right] \\
      &\le \Pr_{P_{x,j}}\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} | \Big| |P_{x,j} \cap P_{u,i}| \ge \frac{s^2}{2 C} \right]\Pr\left[|P_{x,j} \cap P_{u,i}| \ge \frac{s^2}{2 C}\right]
        + \Pr\left[|P_{x,j} \cap P_{u,i}| \le \frac{s^2}{2 C}\right] \\
        &\le (\exp\left( - \frac{s^2}{400C} \right) + \epsilon)\cdot 1 + (\exp(-\frac{s^2}{8 C}) + \epsilon)
        \le 2 \exp\left( - \frac{s^2}{400C} \right) \,.
  \end{align*}

  Substituting this result into Eq. \ref{eq:superhall-specific} gives:
  \begin{align*}
    \Pr\left[ \bigwedge_{(x,j) \in S} \left\{ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i}\right\} \right] \le 2^{|S|} \exp\left( - |S| \frac{s^2}{400C} \right) \,.
  \end{align*}
  Taking a union bound over all $(u,i,S,T)$ tuples gives:
  \begin{align*}
    \Pr&[\text{second part of Property U fails}] \\
      &\le \sum_{(u,i) \in V \times [C/s]} \sum_{k=1}^{s \Delta / C} \sum_{\text{valid $S$ with $|S| = k$}} \sum_{T \subseteq \binom{P_{u,i}}{k-1}} 2^{k} \exp\left( - k \frac{s^2}{400C}\right) \\
      &\le n \cdot \sum_{k=1}^{s \Delta / C} \cdot \binom{n - 1}{k} \left(\frac{C}{s}\right)^k \cdot \binom{s}{k - 1} \cdot 2^{k} \exp\left( - k \frac{s^2}{400C}\right) \\
      &\le n \sum_{k=1}^{s \Delta / C} \left( 2 n C s \exp\left(- \frac{s^2}{400 C}\right) \right)^k \\
      &\le 2 n \cdot 2 n C s \exp\left(- \frac{s^2}{400 C}\right) \qquad\qquad \text{for large enough $s^2/C$} \\
      & \le 4 n^2 \cdot (32 n)^2 \exp(- \frac{2048}{100} \log(n/\delta)) \le \frac{\delta}{2} \qquad\qquad \text{since $s \le C = 32 \Delta$}
  \end{align*}
  Combining this with a union bound over Eq. \ref{eq:puv-size-lb} implies that property U fails to hold with probability $\le \delta$.

  For the second stage of the proof, we consider the following iterative process to color any graph $H$ satisfying the given conditions. Consider an arbitrary ordering $v_1,\ldots,v_n$ of the vertices in $V \times [C/s]$. For a given vertex $v_t$, let $A(v_t)$ be the set of vertices in $\{v_1,\ldots,v_{t-1}\}$ which are adjacent to $(v_t,i)$, and let $B(v_t,i)$ be the set of vertices in 
  $\{v_{t+1},\ldots,v_{n}\}$ which are adjacent to $(v_t,i)$. For each $z \in A(v_t) \cup B(v_t)$, define $U_{t,v_t,z}$ to be the set of colors in $P_{v_t} \cap P_z$ that were already used by edges to vertices in $A(v_t)$ just \emph{after} step $t$. The color assignment chosen will maintain the invariant W that $|U_{t,z,(v_{t'})}| \le \frac{1}{3} |P_z \cap P_{v_{t'}}|$ for all $t' > t$ and $z \in A(v_{t'})$. In other words, that when it is time to color the edges from a future vertex $(v_{t'})$ to $A(v_{t'}$, only a $\le 1/3$ fraction of the initially possible color options will have been used.

  Invariant W automatically holds when $t = 0$, since no edges have been colored. Say the invariant holds at time $t - 1$. Then we are guaranteed that $|U_{t-1,z,v_t}| \le \frac{1}{3} |P_z \cap P_{v_t}|$ for all $z \in A(v_t)$, and want to find color assignments for the edges from $A(v_t)$ to $z$ so that $|U_{t,z,v_t}| \le \frac{1}{3} |P_z \cap P_{v_t}|$ for all $z \in B(v_t)$. To do this, we will first pick a set $F \subseteq P_{v_t}$ that satisfies:
  \begin{align}
    \forall x \in A(v_t):&\quad |P_x \cap P_{v_t} \setminus U_{t-1,x,v_t} \setminus F| \ge \frac{1}{10} |P_x \cap P_{v_t}| \\
    \forall x \in B(v_t):&\quad |(P_y \cap P_{v_t}) \setminus F| \le \frac{1}{3} |P_y \cap P_{v_t}| \end{align}
  That such a set $F$ exists follows by the probabilistic method; say $F$ were chosen so that each element of $P_{v_t}$ is included u.a.r with probability $\frac{7}{10}$. For $i \in P_{v,t}$, let $X_i$ be the indicator random variable for the event that $i \in F$. Then the probability of Eq. \ref{eq:F-backward} is bounded by:
  \begin{align*}
    \Pr&\left[ |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F| \ge \frac{1}{10} |P_x \cap P_{v_t}| \right] \\
      &\le   \Pr\left[ |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F|      \ge \frac{3}{20} |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}| \right] \quad \text{ since $|(P_x \cap P_{v_t}) \setminus U_{x,v}| \ge \frac{2}{3} |P_x \cap  P_{v_t}|$ } \\
      &\le \Pr\left[ \sum_{i \in (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}} X_i \ge \frac{17}{20} |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}| \right] \\
      &\le \exp\left(- \frac{9}{200} |P_x \cap P_{v_t} \setminus U_{t-1,x,v_t}| \right) \qquad \text{by Chernoff bound, since $\mathbb{E}$ of LHS is $\frac{14}{20} |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}|$} \\
      &\le \exp\left(- \frac{3}{100} |P_x \cap P_{v_t}| \right) \qquad \text{since $|(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}| \ge \frac{2}{3} |P_x \cap P_{v_t}|$} \\
      & \le \exp\left(-\frac{3 s^2}{200 C}\right) = \exp\left(- \frac{3072}{25} \log(n/\delta)\right) < \frac{1}{2 n}
  \end{align*}
  And for Eq. \ref{eq:F-forward}:
  \begin{align*}
    \Pr\left[ |(P_x \cap P_{v_t}) \setminus F| \ge \frac{1}{3} |P_x \cap P_{v_t}| \right] 
      &= \Pr\left[ \sum_{i \in (P_x \cap P_{v_t})} X_i \le \frac{2}{3} |P_x \cap P_{v,t}| \right] \\
      &\le \exp\left( -2 \left(\frac{7}{10} - \frac{2}{3}\right)^2 |P_x \cap P_{v,t}| \right) \\
      &\le \exp\left(-\frac{1}{450} |P_y \cap P_v|\right) = \exp\left(-\frac{s^2}{900 C}\right) = \exp\left(- \frac{2048}{225} \log(n/\delta)\right) < \frac{1}{2n}
  \end{align*}
  Applying a union bound for the complements of Eq. \ref{eq:F-forward} and Eq. \ref{eq:F-backward} over all applicable $z$, we find that both conditions hold with positive probability, so a suitable $F$ exists.

  Now that $F$ has been chosen, we will select the colors for the edges from $v_t$ to each $x \in A(v_t)$ from the set $(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F$. Since no colors in $F$ are chosen, for any $z \in B(v_t)$, $U_{t,z,v_t}$ will not contain any element of $F$; thus $|U_{t,z,v_t}| \le |(P_x \cap P_{v_t}) \setminus F| \le \frac{1}{3} |P_x \cap P_{v_t}|$.

  Construct the bipartite graph $J$ between $A(v_t)$ and $P_{v_t}$, where $x \in A(v_t)$ has an edge to each of the colors in $(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F$. We claim there is an an $A(v_t)$-saturating matching $M$ of $J$; given this matching, we assign to edge $\{x,v_t\}$ its matched color $M(x)$. For all $x \in A(v_t)$, we will have $M(x) \in (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F$; since $M(x) \notin U_{t-1,x,v_t}$, the edge color for $\{x,v_t\}$ will not have been used before by any edge adjacent to $x$.
  As the matching assigns a unique color to each edge, the edge coloring constraint will also be satisfied for $v_t$.

  To prove there exists a matching $M$ in $J$, we verify that Hall's condition holds. For any subset $S$ of the vertices in $A(v_t)$, we want to show that
  \begin{align*}
    \left| \bigcup_{x \in S} ((P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F) \right| \ge |S|
  \end{align*}
  The construction of $H$ ensures that $A(v_t)$ and all subsets thereof satisfy the conditions for the second part of Property U (Specifically, $|A(v_t)| \le s \Delta / C$, and that for any $b \in V$ there is at most one $j$ for which $(b,j) \in A(v,t)$.) By this property, we are guaranteed that for all $T \subseteq P_{v_t}$ of size $k-1$, that there exists some $x \in S$ for which $|P_x \cap T| \le \frac{1}{10} |P_x \cap P_{v_t}$. If Hall's condition does not hold for $S$, then there must exist some $T \subseteq P_{v,t}$ for which:
  \begin{align*}
  &\bigcup_{x \in S} ((P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F) \subseteq T \\
  \implies \quad \forall x \in S:\quad & (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F \subseteq T \\
  \implies \quad \forall x \in S:\quad & (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F \subseteq T \cap P_x \\
  \implies \quad \forall x \in S:\quad & |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F| \le |T \cap P_x| \\
  \implies \quad \forall x \in S: \quad& \frac{1}{10} |P_x \cap P_{v_t}| \le |T \cap P_x| \qquad \text{by Eq. \ref{eq:F-backward}}
  \end{align*}
  But by the second part of Property U, there must exist an $x \in S$ for which $\frac{1}{10} |P_x \cap P_{v_t}| > |T \cap P_x|$; this is a contradiction, so it follows that Hall's condition does hold for $S$. Since Hall's condition holds for all $S \subseteq A(v_t)$, $J$ will contain a matching, and step $t$ will ensure invariant W holds for step $t+1$.

  By induction, it follows that invariant W holds for all $t \in [n]$, and thus that the process to color the edges of the graph will always work.

\caption{Inner algorithm:  $O(\Delta \log \Delta)$ edge coloring for graph edge arrival streams which have certain substreams satisfying Property Z, plus reference counting }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of edge arrivals $n$-vertex graph $G=(V,E)$. 
      \Statex Assume $\Delta$ is a power of two
      \Statex Superscript $\cdot^{(\ell)}$ indicates \emph{level} of algorithm

      \Statex
      \Statex \underline{\textbf{Initialize($\ell$, $\Delta^{(\ell)}$, $R$)}:}
        \Statex Input $\Delta^{(\ell)}$ is the maximum degree of the input graph
        \Statex Let $C^{(\ell)} = 32 \Delta^{(\ell)}$
        \State $D^{(\ell)} \gets \emptyset$ be a set of $O(n \log n)$ "overflow" edges 

        \If{ $\Delta^{(\ell)} \ge 256 \log(n/\delta))$}
          \Comment{Condition for \Cref{lem:offline-ea-coloring} to apply}
          \State Let $s^{(\ell)}$ satisfy constraints of \Cref{lem:offline-ea-coloring}
          \State Advice: $\{\sigma_v^{(\ell)}\}_{v \in V}$ are permutations over $[C^{(\ell)}]$, "good" for \Cref{lem:offline-ea-coloring}

          \For{each \emph{layer} $\xi \in [\ceil{\log_{3/2}{\Delta^{(\ell)}}}]$}
            \State $\mathfrak{I}^{(\ell,\xi)} \gets$ \textsc{Initialize}($\ell$,$\xi$,$\Delta$,$C$,$s$,$\{\sigma_v^{(\ell)}\}_{v\in V}$,$R$) from \Cref{alg:det-ea-partial}
          \EndFor
        \EndIf

    \Statex 
    \Statex\underline{\textbf{Process}(edge $\{x,y\}$) $\rightarrow$ \textbf{color} $\in \left[\ceil{\log_{3/2}{\Delta^{(\ell)}}}\right] \times \left[C^{(\ell)}\right]$}
        \If{$\Delta^{(\ell)} \ge 256 \log(n/\delta))$}
          \For{$\xi \in \left[\ceil{\log_{3/2}{\Delta^{(\ell)}}}\right]$} \State Let $c \gets \mathfrak{I}^{(\ell,\xi)}.\textsc{Process}(\{x,y\})$ from \Cref{alg:det-ea-partial}
            \If{$c \ne \bot$}
              \State \textbf{return} color $(\xi, c)$
            \EndIf
          \EndFor
        \EndIf
        \State $D^{(\ell)} \gets D^{(\ell)} \cup \{\{x,y\}\}$ \State Increase reference count for $\{x,y\}$ in $R$
        \State Greedily pick a color class $c \in [C^{(\ell)}]$ not used by any edge in $D^{(\ell)}$ adjacent to $x$ or $y$
        \State $\chi^{(\ell)}_{\{x,y\}} \gets (0,c)$
        \State $M^{(\ell)}_{\{x,y\}} \gets 1$
        \State \textbf{return} color $(0,  c)$
    \end{algorithmic}

Let $B$ be a set of $n$ vertices; let $\Delta$ be an integer, and let $C \in [\Delta, 2 \Delta - 1]$ be another integer. Define $\beta := C / \Delta$. Consider the case where $(2 - \beta) n \ge 32 C$.

  For each $v \in B$, say we have a nonempty set $S_v \subseteq [C]$ of possible colors, where $\sum_{i \in B} |S_i| \le \beta n$. If $G$ is a uniformly random bipartite graph between a set $A$ of size $\floor{n/\Delta}$, then the probability $p(n, \Delta, \beta)$ that $G$ has a valid edge coloring where each edge $(a,b)$ is given a color from $S_b$ is:
  \begin{align}
      p(n, \Delta, \beta) \le \exp(- \frac{1}{2^{13}} (2-\beta)^3 n) \end{align}

Let $W$ be a nonnegative integral random variable where, for all $k \in \mathbb{N}$, $\Pr[W \ge k] \le 1/2^k$. Then $\mathbb{E}[W] \le 1$; and furthermore, for all $t$ for which $e^t \in [1,2)$:
   \begin{align*}
        \mathbb{E}[e^{t W}] \le \frac{1}{2 - e^t}
   \end{align*}

conclusions:
\begin{align*}
        \mathbb{E}[e^{t W}] \le \frac{1}{2 - e^t}
   \end{align*}

nodes.statement:
First,
  \begin{align*}
    \mathbb{E}[W] = \sum_{k=0}^{\infty} \Pr[W \ge k] \le \sum_{k=0} 1/2^{k + 1} = 1
  \end{align*}
  Next,
  \begin{align*}
    \mathbb{E}[e^{t W}] &= \sum_{k=0}^{\infty} e^{t k} \Pr[W = k] \le \sum_{k=0}^{\infty} e^{t k} \frac{1}{2^{k+1}} = \frac{1}{2} \sum_{k=0}^{\infty} \left(\frac{e^t}{2}\right)^k = \frac{1}{2}\cdot\frac{1}{1 - \frac{1}{2}e^t} = \frac{1}{2 - e^t}
  \end{align*}
  The inequality step follows because:

  \begin{align*}
     \sum_{k=0}^{\infty} e^{t k} \left(\frac{1}{2^{k+1}} - \Pr[W = k]\right)
        &= \sum_{k=0}^{\infty} e^{t k} \left((\frac{1}{2^{k}} - \frac{1}{2^{k+1}}) -(\Pr[W \ge k] - \Pr[W \ge k - 1])\right) \\
        &= \sum_{k=0}^{\infty} e^{t k} \left(\frac{1}{2^{k}} - \Pr[W \ge k]\right)
          - \sum_{k=0}^{\infty} e^{t k} \left(\frac{1}{2^{k + 1}} - \Pr[W \ge k - 1]\right) \\
        &= \sum_{k=0}^{\infty} e^{t k} \left(\frac{1}{2^{k}} - \Pr[W \ge k]\right)
          - \sum_{k=1}^{\infty} e^{t (k - 1)} \left(\frac{1}{2^{k}} - \Pr[W \ge k]\right) \\
        &= \left(\frac{1}{2^{0} - \Pr[W \ge 0]}\right) + \sum_{k=1}^{\infty} (e^t - e^{t (k - 1)}) \left( \frac{1}{2^{k} - \Pr[W \ge k]}\right) \\
        &= 0 + \sum_{k=1}^{\infty} e^{t (k -1)}(e^t - 1) \left(\frac{1}{2^{k}} - \Pr[W \ge k]\right) \ge 0
  \end{align*}

Let $k = O(d^3 + d \ln(1/\epsilon))$ be the constant for which $k$ Thorp shuffle steps would permute $[C] = [2^d]$ within total variation distance of $\epsilon$ of the uniform distribution over permutations on $[2^d]$.



  The switching network $\mathcal{N}$ corresponding to the $k$ Thorp shuffle steps has depth $k$ and uses exactly $k C / 2$ gates. Assign each gate a unique number in $[kC/2]$. Then given a uniformly random bit vector $x \in \{0,1\}^{k C / 2}$, we evaluate the switching network by having the gate numbered $i$ switch its inputs iff $x_i = 1$. A key property of switching networks is that one can evaluate their action on a single
  input by only evaluating one gate per layer -- for this network, only $k$ gates. Reversing the order in which the layers are applied will produce the inverse of the original permutation. Thus, one can evaluate
  $\mathcal{N}(i)$ by reading only $k$ entries of $x$, and similarly for and $\mathcal{N}^{-1}{i}$.

  Now, say the bits of $x$ are the output of a hash function drawn from a $k s$-wise independent hash family. (For example, using a family of \cite{WegmanC81}, let $h = \ceil{\log_2{k C / 2}}$, take the family of random polynomials of degree $k s - 1$ inside $\mathbb{F}_{2^{h}}$, and output the least bit of the output. The polynomial coefficients can be encoded using $k s h = O(k s \log(C))$ bits, and the polynomials evaluated at any point in $O(k s h^2 ) = O(k s (\log C)^2 )$ time.)

  If $\pi$ is a uniformly random permutation on $[C]$, then for all lists of distinct $h_1,\ldots,h_s$, and all lists of distinct $j_1,\ldots,j_s$, we have
  \begin{align*}
    \Pr[\bigwedge_{i\in[s]} \pi(h_i) = j_i] = \frac{1}{\prod_{i \in [s]} (C - i + 1)}
  \end{align*}

  Now, let $f : \{0,1\}^{k C/2} \times [C] \mapsto [C]^k$ be the function which maps the gate-controlling vector $x \in \{0,1\}^{k C / 2}$ and an input $a \in [C]$ to the path $b_1,\ldots,b_k$ that $a$ takes through the switching network $\mathcal{N}$ if its gates are configured according to $x$. The last node of this path, $f(x, a)_k$ is the output of $\mathcal{N}$ given $x$ and $a$. Each path $P = (a,b_1,\ldots,b_k)$ through the switching network corresponds to a restriction $R_P \in \{0,1,\star\}^{k C / 2}$ which has value $\star$ on gates not touched by the path, and for each gate traversed by the path assigns either $0$ or $1$ depending on whether a straight or switched configuration of the gate is compatible with $P$. Since all paths through the network have length $k$, $R_P$ only sets $k$ coordinates. Now, for each pair $(a,b) \in [C]^2$, let 
  \begin{align*}
    \mathcal{F}_{a,b} = \{R_P : P = (a,b_1,\ldots,b_{k-1},b) \text{ is a possible path}\}
  \end{align*}

  Then, for lists $(h_1,\ldots,h_s)$, $(j_1,\ldots,j_s)$, define 
  \begin{align*}
    \mathcal{K}_{h_1,\ldots,h_s,j_1,\ldots,j_s} = \{ R \in \{0,1,\star\}^{k C / 2} : \forall i \in [k], \exists T \in \mathcal{F}_{h_i,j_i} \text{where $R$ is a minimal refinement of $T$}  \}\,,
  \end{align*}
  i.e., the set of minimal restrictions for vectors in $\{0,1\}^{k C / 2}$ which
  completely determine the paths through the switching network of inputs $(h_1,\ldots,h_s)$. 

  Now, let $Y \in \{0,1\}^{k C / 2}$ be $k s$-wise independent, and $X \in \{0,1\}^{k C / 2}$ be fully independent. We have:
  \begin{align*}
    \Pr[\bigwedge_{i\in[s]} f(Y, h_i)_k = j_i] &= \sum_{R \in \mathcal{K}_{h_1,\ldots,h_s,j_1,\ldots,j_s}} \Pr[Y \text{ compatible with $R$}] \\
    &= \sum_{R \in \mathcal{K}_{h_1,\ldots,h_s,j_1,\ldots,j_s}} \Pr[X \text{ compatible with $R$}] \\
    &= \Pr[\bigwedge_{i\in[s]} f(X, h_i)_k = j_i]
  \end{align*}
  where the second inequality follows because each restriction $R \in \mathcal{K}_{h_1,\ldots,h_s,j_1,\ldots,j_s}$ only constrains $s k / 2$ coordinates
  corresponding to the gates on the paths in the switching network from $h_1,\ldots,h_s$ to $j_1,\ldots,j_s$ that it fixes.

  Thus,
  \begin{align*}
      &\frac{1}{2} \sum_{\text{distinct $b_1,\ldots,b_k$ in $[C]$,}} \left| \Pr\left[\bigwedge_{i \in [s]} \{ f(X, h_i)_k = j_i \} \right] - \frac{1}{\prod_{i \in [s]} (C - i + 1)} \right| = \\
      &\frac{1}{2} \sum_{\text{distinct $b_1,\ldots,b_k$ in $[C]$,}} \left| \Pr\left[\bigwedge_{i \in [s]} \{ f(Y, h_i)_k = j_i \} \right] - \frac{1}{\prod_{i \in [s]} (C - i + 1)} \right| \le \epsilon
  \end{align*}
  which proves that the switching network evaluated on $X$ produces outputs that are $(\epsilon,s)$-wise independent.

We claim \Cref{alg:gen-to-bpt} works for sufficiently large $n$.

  \begin{algorithm}[htb!]
    \caption{Algorithm to partition general graph edges into bipartite graphs }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of edges in an $n$-vertex graph $G=(V,E)$
      \Statex
      \Statex \underline{\textbf{Initialize}:}
      \For{$v \in V$}
        \State $\deg_{F_i}(v) \gets 0$
      \EndFor
      \State Setup binary code $\mathcal{C}$ of length $t := 4 \ceil{\log n}$ from \Cref{cor:practical-binary-codes}
      \For{$i \in [t]$}
        \State Let $F_i$ be the bipartition with parts $A_i = \{v \in V : \mathcal{C}(v)_i = 0 \}$ and $B_i = \{v \in V : \mathcal{C}(v)_i = 1 \}$
      \EndFor

    \Statex 
    \Statex\underline{\textbf{Process}(edge $\{x,y\}$)}
      \State Let $\deg(x) = \sum_{i \in [t]} \deg_{F_i}(x)$ and $\deg(y) = \sum_{i \in [t]} \deg_{F_i}(y)$.
      \For{$i \in [t]$}
          \If{$\mathcal{C}(x)_i \ne \mathcal{C}(y)_i$ and $\deg_{F_i}(x) \le 1200 \deg(x) / t$ and $\deg_{F_i}(y) \le 1200 \deg(y) / t$} \State Increase $\deg_{F_i}(x)$ and $\deg_{F_i}(y)$ by 1
              \State Assign edge $\{x,y\}$ to $F_i$
              \State \textbf{return}
          \EndIf
      \EndFor
      \State unreachable \end{algorithmic}
  \end{algorithm}

  It is clear that at each point in time, for all $v \in V$ and $i \in [t]$, the algorithm will have $\deg_{F_i}(v)$ be the number of edges assigned to $F_i$ incident on $v$.

Consider \Cref{alg:bpt-rand-va-edgecol}. This algorithm will have the required properties if $\Delta \ge 6 \ln \frac{n}{\delta}$; if $\Delta$ is smaller, convert the vertex arrival stream to an edge arrival stream and pass it to \Cref{alg:simple-greedy}, which guarantees a $2\Delta-1$ coloring of the graph using $O(n \Delta) = O(n \ln \frac{n}{\delta})$ bits of space.

  \begin{algorithm}[htb!]
    \caption{Randomized algorithm for $5 \Delta$ edge coloring for (adversarial) one sided vertex arrival bipartite streams }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of vertex arrivals $n$-vertex graph $G=(A \sqcup B,E)$
      \Statex
      \Statex \underline{\textbf{Initialize}:}
      \State Let $C = 5 \Delta$.
      \For{$v \in B$}
        \State Let $\sigma_v$ be a uniformly random permutation over $[C]$ \Comment{constructed on demand from random oracle bits}.
        \State $h_v \gets 1$.

      \EndFor

    \Statex \underline{\textbf{Process}(vertex $x$ with multiset $M_v$ of edges to $B$)}
      \State Let $S \gets \emptyset$ \Comment{Set of colors $M_x$ will have used so far}
      \For{$e = \{x,y\}$ in $M_x$, in arbitrary order}
        \While{$h_y \le C \land \sigma_y[h_y] \in S$} \State $h_y \gets h_y + 1$
        \EndWhile
        \If{$h_y > C$}\State abort \EndIf
        \State Assign color $\sigma_y[h_y]$ to $e$ \State $S \gets S \cup \{\sigma_y[h_y] \}$
        \State $h_y \gets h_y + 1$ \EndFor
    \end{algorithmic}
  \end{algorithm}

We now consider the distribution of $V_{y,i}$, conditioned on both the value of the
  variable $S$ at the time the $i$th edge was processed, and on the parts of
  the permutation $\sigma_y$ which the algorithm has read so far, $\sigma_y[1..{h_y-1}]$.
  \begin{align*}

    \Pr[V_{y,i} \ge k \mid S, \sigma_y[1..{h_y-1}]] &= \Pr[\sigma_y[h_y,\ldots,h_y + k - 1] \subseteq S \mid S, \sigma_y[1..{h_y-1}]] \\
      &= \binom{|S \cap \sigma_y[h_y,...,C]|}{k} / \binom{C - h_y - 1}{k}  \\
      & \le \binom{\Delta}{k} / \binom{2 \Delta}{k} \qquad\qquad \text{since $|S|\le\Delta$, $h_y \le C - 2\Delta$} \\
      &\le \frac{\Delta\cdot (\Delta-1) \cdots (\Delta -k +1)}{2\Delta \cdot (2\Delta-1) \cdots (2\Delta -k +1)} \le \frac{1}{2^k}
  \end{align*}

Since this bound holds for all values of $S$ and all $\sigma_y[1..{h_y-1}]$, in particular we
  have
  \begin{align*}
    \Pr[V_{y,i} \ge k | (V_{y,j})_{j < i}] = \mathbb{E}_{\text{$S,\sigma_y[1..{h_y-1}]$ compat with $(V_{y,j})_{j < i}$}} \Pr[V_{y,i} \ge k |S,\sigma_y[1..{h_y-1}]] \le \frac{1}{2^k}
  \end{align*}

Since $h_v \le \Delta + \sum_{i\in\Delta} V_{y,i}$, this implies that
  \begin{align*}
    \Pr[h_v \ge C] \le \Pr[h_v \ge C - 2 \Delta] = \Pr[h_v \ge 3 \Delta] \le \Pr[\sum_{i=1}^{\Delta} V_{y,i} \ge 2 \Delta] \le  \exp(-\Delta/6)
  \end{align*}

Since the $(\sigma_i)_{i\in [w]}$ are $(\epsilon,t)$-wise independent, in particular we have for any $i\in [w]$,$j \in [C]$, that $\Pr\left[j \in \sigma_i[F_i]\right] \le s_i / C + \epsilon$, and for any $Q \subseteq [C]$ with $|Q| \le t$, that 
  \begin{align}
    \Pr[Q \subseteq \sigma_i[F_i]] = \frac{s_i \cdot (s_i-1) \cdots (s_i - |Q| + 1)}{C \cdot (C-1) \cdots (C - |Q|+1)} + \epsilon \le \left(\frac{s_i}{C}\right)^{|Q|} \end{align}

Note that
  \begin{align}
    \Pr\left[\left| \bigcup_{i \in [w]} \sigma_i[F_i] \setminus X \right|  < \frac{1}{8} \sum_{i \in [w]} s_i \right] & \le \Pr\left[\sum_{i \in [w]} Y_{B_i,i} \ge \frac{7}{8} \sum_{i\in[w]} s_i \right] \end{align}

Let $\gamma = (\frac{7}{8} \sum_{i\in[w]} s_i) / \mathbb{E}[\sum_{i \in [w]} Y_{B_i,i}] $; this is $\ge 7/5$. Applying a modified proof of the Chernoff bound/Azuma's inequality to the right hand side of Eq. \ref{eq:ybi-excess} gives:
  \begin{align*}
    &= \inf_{z > 0} \Pr\left[\exp\left(z \sum_{i \in [w]} Y_{B_i,i}\right) \ge \exp\left(\gamma z \mathbb{E}[\sum_{i \in [w]} Y_{B_i,i}]\right) \right] \\
    &\le  \inf_{z > 0} \frac{\exp\left(z \sum_{i \in [w]} Y_{B_i,i}\right) }{\exp\left(\gamma z \mathbb{E}[\sum_{i \in [w]} Y_{B_i,i}]\right)} \qquad\qquad \text{by Markov's inequality} \\ 
    &= \inf_{z > 0} \exp\left(z \sum_{i \in [w]} (Y_{B_i,i} - \gamma \mathbb{E}[Y_{B_i,i} ])\right) \\
    &= \inf_{z > 0} \mathbb{E}\left[\exp\left(z (Y_{B_1,1} - \gamma \mathbb{E}[Y_{B_1,1}])\right) \cdots \mathbb{E}\left[\exp\left(z (Y_{B_w,w} - \gamma \mathbb{E}[Y_{B_w,w}])\right) \big\vert Y_{B_1,1}, \ldots, Y_{B_{w-1},w-1}\right] \cdots  \right] \\
    &\le \inf_{z > 0} \prod_{i \in [w]} \max_{B: \frac{1}{8} C \le |B| \le \frac{5}{8} C} \mathbb{E} \exp\left(z (Y_{B,i} - \gamma \mathbb{E}[Y_{B,i}])\right) \qquad\qquad \text{bounding terms from the inside out} \\
    &= \inf_{z > 0} \prod_{i \in [w]} \max_{B: \frac{1}{8} C \le |B| \le \frac{5}{8} C} \frac{\mathbb{E} \exp\left(z Y_{B,i}\right)}{\exp\left(\gamma z\mathbb{E}[Y_{B,i}])\right) } \\
    &\le \inf_{z > 0} \prod_{i \in [w]} \max_{B: \frac{1}{8} C \le |B| \le \frac{5}{8} C} \frac{\exp\left({\frac{s_i |B|}{C} (e^z - 1)} \right) +\frac{(z s_i)^{t+1}}{(t+1)!} e^{z s_i} +  \epsilon t C}{\exp\left(\gamma z\mathbb{E}[Y_{B,i}])\right) } \qquad\qquad \text{by Eq. \ref{eq:moment-bound} }
  \end{align*}

$\delta \in (0,1)$ is a parameter governing the probability that the  \Cref{alg:bpt-det-va-edgecol} will fail to be a correct deterministic algorithm, if its advice is chosen randomly; if one just wants a deterministic algorithm, setting $\delta = 1/2$ suffices. If $\Delta \le \log\frac{n \Delta}{\delta}$, use the simple greedy algorithm (\Cref{alg:simple-greedy}). Otherwise, use \Cref{alg:bpt-det-va-edgecol}.

  \begin{algorithm}[htb!]
    \caption{Deterministic algorithm for $O(\Delta)$ edge coloring for (adversarial) one sided vertex arrival bipartite streams, using $\widetilde{O}(n)$ bits of advice }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of vertex arrivals for $n$-vertex graph $G=(A \sqcup B,E)$ of max degree $\Delta$
      \Statex
      \Statex $\delta \in (0,1)$ is a parameter so that, if the advice is chosen randomly, it will work for all inputs with probability $\ge 1 - \delta$
      \Statex
      \Statex \underline{\textbf{Initialize}:}
      \Statex Let $C = 2^{18} \Delta$. 
      \Statex Let $s = \ceil{2^{18} \log\frac{n \Delta}{\delta}} $.
      \Statex Advice: $(\sigma_v)_{v \in B}$, where each $\sigma_v$ is a permutation over $[C]$. If chosen randomly, each is $(\epsilon,s)$-wise independent for $\epsilon \le C^{-s - 1}$

      \For{$v \in B$}
        \State $b_v \gets 1$.
        \State $Q_v \gets [s]$.
      \EndFor

    \Statex \underline{\textbf{Process}(vertex $x$ with multiset $M_x$ of edges to $B$)}
      \Statex Let $d_{x,y}$ be the number of times edge $\{x,y\}$ is in $M_x$
      \For{each $y \in B$ with $d_{x,y} > 0$}
        \If{$d_{x,y} < \frac{1}{16} s$}
          \State Let $F_y = (b_y -1) s + Q_y$ \Else
          \State Let $F_y = ((b_y -1) s + Q_y) \sqcup [b_y s, b_y + \ceil{\frac{64 d_{a,b}}{s}} s]$ \EndIf
      \EndFor
      \State Construct bipartite graph $H$ from $M_x$ to $[C]$, edge $e \in M_x$
      is linked to all $c \in \sigma_y[F_y]$. \State Compute an $M_x$-saturating matching $P$ of $H$. \For{each $e \in M_x$}
        \State Assign color $P(e)$ to $e$
        \If{$d_{x,y} < \frac{1}{16} s$}
          \State Remove $\sigma_y^{-1} - (b_y - 1)s$ from $Q_y$
        \EndIf
      \EndFor
      \For{each $y \in B$ with $d_{x,y} > 0$}
        \If{$d_{x,y} < \frac{1}{16} s$}
          \If{$|Q_y| \le s - \frac{1}{2^{17}} s$}
            \State $b_y \gets b_y + 1$ \State $Q_y \gets [s]$
          \EndIf
        \Else
          \State $Q_y \gets [s]$
          \State $b_y \gets b_y + \ceil{\frac{2 d_{x,y}}{s}} + 1$ \EndIf
      \EndFor

    \end{algorithmic}
  \end{algorithm}

For a given vertex $y$, as the algorithm runs, $b_y$ will be increased, by either Line \ref{step:bpt-det-va-edgecol-small-block} or \ref{step:bpt-det-va-edgecol-large-block}. Line \ref{step:bpt-det-va-edgecol-small-block} only triggers when $|Q_y| \le s - \frac{1}{2^{17}} s$, which requires that vertex $y$ has received $\ge \frac{1}{2^{17}} s$ incident edges since the last time $b_y$ was increased. Since there will be at most $\Delta$ edges incident to $y$, the total increase to $b_y$ from this line over the course of the algorithm will be $\le \Delta / (\frac{1}{2^{17}} s) = 2^{17} \Delta / s$. On the other hand, Line \ref{step:bpt-det-va-edgecol-small-block} only triggers when $d_{x,y}\ge \frac{1}{16} s$, and then increases $b_y$ by $\ceil{64 d_{x,y} / s} + 1$. Since $\sum_{x \in A} d_{x,y} \le \Delta$,
  \begin{align*}
    \sum_{x \in A : d_{x,y} > \frac{1}{16} s} \left(\ceil{\frac{64 d_{x,y}}{s}} + 1\right)
    \le \sum_{x \in A : d_{x,y} > \frac{1}{16} s} \left(\frac{64 d_{x,y}}{s} + 2\right) \le \sum_{x \in A : d_{x,y} > \frac{1}{16} s} \frac{96 d_{x,y}}{s}  \le \frac{96 \Delta}{s}
  \end{align*}
  Thus, the total increase in $b_y$ will be $\le (2^{17}+96) \Delta / s$, and $b_y$ will always be $\le (2^{17}+97) \Delta / s$. Looking at the construction
  of the set $F_y$ on Lines \ref{step:bpt-det-va-edgecol-low-deg-fy} and \ref{step:bpt-det-va-edgecol-high-deg-fy}, we see that it will only ever contain elements which are $\le (2^{17}+98) \Delta$. Since $C = 2^{18} \Delta \ge (2^{17}+98) \Delta$, it follows that computing $\sigma_y[F_y]$ will never index out of range.

Since whether the constructed graph $H$ has a matching does not depend on the value of $x$, only on the number of edges arriving at a given $y \in B$, we do not need to take a union bound over all possible sets $M_x$. Instead, define a configuration by a tuple $(S,(d_y)_{y \in S},(b_y)_{y \in S},(Q_y)_{y \in S})$. The set $S$ gives the neighborhood of $x$, and for each $y \in S$ we set $d_y = d_{x,y}$. The values $b_y,Q_y$ match the values from the algorithm at the time $M_x$ arrives. Note that the set $F_y$ is a function of $b_y$, $Q_y$, and $d_y$, and for fixed $b_y,Q_y$ is monotone increasing as a function of $d_y$. We do \emph{not} need any extra cases to handle Hall's condition for subsets of $M_x$; consider any subset $M_x' \subseteq M_x$, and let $S',d_{y}',F_y'$ correspond to $M_x'$. Then because $F_y' \subseteq F_y$ for each $y \in S'$, if Hall's condition holds for the configuration $(S',(d_y')_{y \in S'},(b_y)_{y \in S'},(Q_y)_{y \in S'})$, then
  \begin{align*}
    \left|\bigcup_{y \in S'} F_{y}\right| \ge \left|\bigcup_{y \in S'} F_{y}'\right| \ge \sum_{y \in S'} d_y'
  \end{align*}
  which implies that Hall's condition also holds for the subset $M_x'$ within the bipartite graph $H$ constructed for $M_x$.

Each configuration $(S,(d_y)_{y \in S},(b_y)_{y \in S},(Q_y)_{y \in S}$ can be split into $O(\log \Delta)$ different "level configurations". Let $\tau = s / 16$; then for each vertex $y$, if $d_y < \tau$, the algorithm will choose $F_y$ using Line \ref{step:bpt-det-va-edgecol-low-deg-fy} to be a subset of size $\le s$ and $\ge s (1 - 2^{-17}) \ge s / 2$; and if $d_y \ge \tau$, the algorithm will choose $F_y$ using Line \ref{step:bpt-det-va-edgecol-high-deg-fy}, to be a subset of size $\ge 64 d_y$. Define $L_0 = \{y \in S : d_y < \tau\}$. For each $\ell \in \{1,\ldots,\lambda\}$, for $\lambda = \ceil{\log{\Delta}}$ let $L_\ell = \{y \in S : 2^{\ell - 1} \tau \le d_y < 2^{\ell} \tau\}$. Also write $L_{> \ell} = \bigcup_{j > \ell} L_j$. Within each "level", the values of $d_y$ are either all small ($< \tau$), or all within a factor $2$ of each other. We will show that with high probability, the following two conditions hold:
  \begin{align}
    \forall \ell \ge 1, \forall (L_\lambda,\ldots,L_{\ell+1}) \text{ where } \max_{i > \ell} {(3/2)^{i - \ell} |L_i|} \le |L_\ell|,& \forall {d_y,b_y,Q_y \text{ for } y \in \bigsqcup_{j \ge \ell} L_\ell} : \nonumber\\
    & \left| \left(\bigcup_{y \in L_\ell} \sigma_y[F_y]\right) \setminus \left(\bigcup_{y \in L_{> \ell}} \sigma_y[F_y]\right) \right| \ge 8 \sum_{y \in L_0} d_y \\

    \forall (L_\lambda,\ldots,L_1) \text{ where } \max_{i > 0} {(3/2)^{i} |L_i|} \le |L_0|, & \forall {d_y,b_y,Q_y \text{ for } y \in \bigsqcup_{j \ge 0} L_\ell} : \nonumber \\
    & \left| \left(\bigcup_{y \in L_0} \sigma_y[F_y]\right) \setminus \left(\bigcup_{y \in L_{> 0}} \sigma_y[F_y]\right) \right| \ge \sum_{y \in L_0} d_y \end{align}

Since \Cref{lem:approx-indep-large-anticoncentration}  and \Cref{lem:approx-indep-small-anticoncentration} both ensure a $\exp( - \Omega(s |L_i|))$ type upper bound for the probability of conditions from Eqs. \ref{eq:hall-abundant} and \ref{eq:hall-end-ok}, we can bound the probability that none of the individual event fails in a single sum. Since for each $y$, $Q_y$ is refreshed after at least $s/2^{17}$ elements are removed from it, there are only $\sum_{i=0}^{\ceil{s/2^{17}}} \binom{s}{i} \le 2^{s H(1/2^{16})} \le \exp(s / 2^{11})$ possible values for $Q_y$; here $H$ is the binary entropy function.
  \begin{align*}
    \Pr &[\text{Eqs. \ref{eq:hall-abundant} and \ref{eq:hall-end-ok} hold}]  \\
      &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \sum_{\underset{\text{all $|L_j| \le (2/3)^{j - \ell} w$}}{L_\lambda,\ldots,L_\ell}} \sum_{(d_y,b_y,Q_y)_{y \in \bigsqcup_{j \ge \ell} L_j}} \exp(-  s w / 2^9) \\
      &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \prod_{j \ge \ell} \left((n+1) C^2 \exp(s/2^{11})\right)^{(2/3)^{j - \ell} w} \exp(-  s w / 2^9) \\
      &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \left((n+1) C^2 \exp(s / 2^{11}) \right)^{3 w} \exp(- s w / 2^9)  \\ 
      &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \left(n C\right)^{6 w} \exp(- s w / 2^{11}) \qquad  \text{since $(n+1) \le n^2$ and $2^{-9} - 3 \cdot 2^{-11} = 2^{-11}$} \\ 
      &\le \sum_{\ell \in \{0,\ldots,\lambda\}} \sum_{\underset{\text{where $|L_\ell| = w$}}{w \in \{1,\ldots,\Delta\}}} \exp(- s w / 2^{12}) \qquad \text{since $s \ge 6 \cdot 2^{12} (18 + \log(n \Delta)) \ge 6 \cdot 2^{12} \ln(n C)$} \\
      &\le (\lambda + 1) \Delta \exp(-s / 2^{12}) \le \delta \qquad \text{since $s \ge 2^{13} \log(\Delta/\delta) \ge 2^{13} \ln(\Delta/\delta)$}
  \end{align*}
  Thus,
  \begin{align*}
    \Pr[\text{any configuration fails Hall's condition}]  \le \delta \,.
  \end{align*}

The W-streaming edge-arrival algorithm is given by \Cref{alg:va-to-ea-conversion}. The algorithm uses $s = O(\sqrt{\Delta})$ instances of $\mathcal{A}$. This algorithm maintains a pool $P$ of edges, and whenever it receives a new edge it adds it to the pool. Edges with high multiplicity ($\widetilde{\Omega}(\sqrt{\Delta}/\log(n^2/\delta))$ in $P$ are moved to a different pool $L$; since there are not many of this type, they can be stored using only $\widetilde{O}(n\sqrt{\Delta})$ space. When a vertex $v$ reaches a high degree ($\ge\sqrt{\Delta}$) in the pool, it and its incident edges are removed from $P$ and assigned to a random instance of $\mathcal{A}$ which has not yet received $v$. At the end of the stream, all edges still stored in either $P$ or $L$ are colored.

  \begin{algorithm}[htb!]
    \caption{W-streaming algorithm for $O(\Delta)$ edge coloring on edge-arrival stream given black-box access to algorithm $\mathcal{A}$ for $C \Delta$ edge coloring on vertex-arrival stream }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of edge arrivals for $n$-vertex graph $G=(A \sqcup B,E)$
      \Statex
      \Statex \underline{\textbf{Initialize}:}
      \State Let $s = 2 \ceil{\sqrt{\Delta}}$ 
      \State Let $\tau = \floor{\frac{\sqrt{\Delta}}{9 \ln(n/\delta)}}$ 

      \State $P \gets \emptyset$ is a multiset of edges -- used to cache all arriving edges
      \State $L \gets \emptyset$ is a multiset of edges -- used to efficiently store certain edge types which have high multiplicity 

      \For{$i \in [s]$}
        \State $\mathcal{I}^{(i)} \gets$ instance of algorithm $\mathcal{A}$ for graphs of max degree $\ceil{4 \Delta / s}$; this will use $C \ceil{4 \Delta / s}$ colors
        \State $x^{(i)} \gets [0,\ldots,0] \in \{0,1\}^A$, tracks for which vertices $w$ in $A$ the instance $\mathcal{I}^{(i)}$ has received $(w,M_w)$
      \EndFor

    \Statex \underline{\textbf{Process}(edge $\{x,y\}$)}
      \State $P \gets P \cup \{\{x,y\}\}$.

      \If{edge $\{x,y\}$ has multiplicity > $\tau$ in $P$}
        \State Remove all copies of $\{x,y\}$ from $P$, and add them to $L$ \State \textbf{return}
      \EndIf

      \If{$\exists v \in A$ with degree $\ge \ceil{\sqrt{\Delta}}$ in $P$}
          \State Pick random $i$ from $\{ j \in [s]: x^{(j)}_v = 0\}$ \State $x^{(i)}_v \gets 1$
          \State Let $M_v$ be edges incident on $v$ in $P$
          \State Send $(v,M_v)$ to $\mathcal{I}^{(i)}$ to be colored \State Remove $M_v$ from $P$
      \EndIf

    \Statex \underline{\textbf{End of Stream}}
      \State Color edges in $P \cup L$ greedily using an independent set of $2\Delta - 1$ colors
    \end{algorithmic}
  \end{algorithm}

We now apply the multiplicative (Chernoff-like) form of Azuma's inequality, on the $[0,1]$ random variables $Y_1,\ldots,Y_\Delta$, defined by $Y_j := X_j / \tau$. Let $\alpha = \mathbb{E}[\sum_{j \in \Delta} Y_j]$.
  \begin{align*}
    \Pr\left[\sum_{i \in [\Delta]} X_j \ge 4 \Delta / s\right] &= \Pr\left[ \sum_{i \in [\Delta]} Y_j \ge \frac{4 \Delta}{s \tau} \right] = \Pr\left[ \sum_{i \in [\Delta]} Y_j \ge \left(1 + \left(\frac{4 \Delta}{s \tau \alpha} - 1\right)\right) \alpha \right] \\
      &\le \exp\left( - \frac{1}{3} \left(\frac{4 \Delta}{s \tau \alpha} - 1\right) \cdot \alpha \right) \qquad\qquad \text{since $\frac{4 \Delta}{s \tau \alpha} - 1 > 1$} \\
      &\le \exp\left( - \frac{1}{3} \frac{2 \Delta}{s \tau \alpha}\cdot \alpha \right) =  \exp\left( - \frac{2}{3} \frac{\Delta}{s \tau} \right) \\
      &= \exp\left( - \frac{2 \Delta}{3 \cdot 2 \ceil{\sqrt{\Delta}} \floor{\sqrt{\Delta} / (9 \ln(n/\delta))}} \right) \\
      &\le \exp\left( - 2 \ln(n/\delta)\right) \le \frac{\delta}{n^2} \qquad\qquad \text{since $2 \ceil{\sqrt{\Delta}} \le 3 \sqrt{\Delta}$ and $1/\floor{x} \ge 1/x$}
  \end{align*}

We will first show that of the following two classes of $m$ events, the probability that any of the events is true is $\le \delta / 2$.
  \begin{align*}
    \forall \{u,v\} \in G: H_{\{u,v\}} & := \left\{ D_{\{u,v\}} \le \frac{1}{2} s^2/C \right\} \\
    \forall (u,v) \text{ where } \{u,v\} \in G: J_{u,v} & := \left\{ \sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}| \ge  2 \cdot \frac{3}{2} \frac{s^3}{C^2} \frac{\Delta s}{C} \right\} \\
  \end{align*}

To bound the probability of $H_{\{u,v\}}$, we let $X_1,\ldots,X_C$ be indicator random variables where $X_i = 1$ iff $i \in P_{u, b_{u,\{u,v\}}}$.  Since the $X_i$ are negatively associated\cite{JoagDevP83}, the proof of the Chernoff bound holds, and 
  \begin{align*}
    \Pr[ |D_{\{u,v\}}| \le \frac{1}{2} s^2/C ] &= \Pr[ D_{\{u,v\}} \le \frac{1}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &= \Pr[ \sum_{i \in [P_{v, b_{v,\{u,v\}}}]} X_i \le \frac{1}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &\le \exp( - \frac{1}{8} \mathbb{E}[D_{\{u,v\}}])= \exp(- \frac{s^2}{8 C} )  \\
       &\le \exp(- 16 \log\frac{n}{\delta}) \le \frac{\delta}{2 n^2}
  \end{align*}

To bound the probability of the events $\{J_{u,v}\}$, we will show that $|D_{u,v}|$ is not too large w.h.p, and conditioned on that, the sum $\sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}|$ is not too large w.h.p. With $\{X_i\}_{i\in[C]}$ as defined above:
  \begin{align*}
    \Pr[ |D_{\{u,v\}}| \ge \frac{3}{2} s^2/C ] &= \Pr[ D_{\{u,v\}} \ge \frac{3}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &\le  \Pr[ \sum_{i \in [P_{v, b_{v,\{u,v\}}}]} X_i \ge \frac{3}{2} \mathbb{E}[D_{\{u,v\}}] ] \\
       &\le \exp( - \frac{1}{10} \mathbb{E}[D_{\{u,v\}}]) = \exp(- \frac{s^2}{10 C} ) \\
       &\le \exp(- \frac{128}{10} \log\frac{n}{\delta})\le \frac{\delta}{4 n^2}
  \end{align*}
  The permutations $\{\sigma_x\}_{x \in M_{u,v}}$ are independent of $\sigma_u$ and $\sigma_v$. For each $x \in M_{u,v}$, let $Y_{1,x},\ldots,Y_{C,x}$ be indicator random variables
  where $Y_{i,x}$ is 1 iff $i \in P_{x, b_{x,\{x,u\}}}$, and zero otherwise. Due to the frequency of free color buffer refreshing, $|M_{u,v}| \le s \Delta / C$; and since $|P_{x, b_{x,\{x,u\}}}| = s$, $\mathbb{E} Y_{i,x} = s/C$. Since the $\{Y_{i,x}\}_{i \in D_{\{u,v\}}, x \in M_{u,v}}$ are negatively associated, we can apply a Chernoff bound. If we assume that $|D_{\{u,v\}}| \le \frac{3 s^2}{2 C}$, then we have:
  \begin{align*}
    \Pr\left[ \sum_{x \in M_{u,v}} |D_{\{u,v\}} \cap P_{x,b_{x,\{x,u\}}}| \ge 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C}\right]
      &= \Pr\left[ \sum_{i \in D_{\{u,v\}}, x \in M_{u,v}} Y_{i,x} \ge 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} \right] \\
      &\le \exp\left( - \frac{1}{8} \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} \right) \\
      &\le \exp(- 12 (\log(n/\delta))^2) \le \frac{\delta}{4 n^2}
  \end{align*}
  Thus, the probability that either $|D_{\{u,v\}}| \ge \frac{3 s^2}{2 C}$ or event $J_{u,v}$ does not hold is $\frac{\delta}{2 n^2}$.

To do this, we will use the following lower bound:
  \begin{align}
    |F_u \cap F_v| \ge |D_{\{u,v\}}| - \sum_{x \in M_{u,v}} W_{x,u} - \sum_{x \in M_{u,v}} W_{x,v} \end{align}
  Here $W_{x,u}$ is the indicator random variable for the event that the color chosen for
  $\{x,u\}$ was in $D_{\{u,v\}}$. The lower bound overcounts the number of colors in $D_{\{u,v\}}$ that have been removed from $F_u \cap F_v$.

The base case of the induction (0 edges) is immediate. Assume that we are processing
  edge $\{u,v\}$, and that all edges $\{x,y\}$ earlier in the stream, when they were processed,
  had $|F_x \cap F_y| \ge \frac{s^2}{4 C}$. For each $x \in M_{u,v}$, the color $\chi_{\{x,u\}}$ was drawn uniformly at random from \emph{some} set $F_x \cap F_u$, which we assume satisfies $|F_x \cap F_u| \ge \frac{s^2}{4 C}$. For any subset $H$ of $D_{\{x,u\}}$ of size $\frac{s^2}{4 C}$, if $\hat{\chi}$ is chosen u.a.r. from $H$, then 
  \begin{align*}
    \Pr[\hat{\chi} \in D_{\{u,v\}}] \le \frac{|H \cap D_{\{u,v\}}|}{|H|} \le \frac{4 C}{s^2} |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}|
  \end{align*}
  Conditioned on the color choices of all earlier edges, we thus have $\mathbb{E} W_{x,u} \le \frac{4 C}{s^2} |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}|$. Thus
  \begin{align*}
    \mathbb{E}\left[\sum_{x \in M_{u,v}} W_{x,u} + \sum_{x \in M_{v,u}} W_{x,v}\right] &\le \frac{4 C}{s^2} \left(\sum_{x \in M_{u,v}}  |P_{x,b_{x,\{x,u\}}} \cap D_{\{u,v\}}| + \sum_{x \in M_{v,u}}  |P_{x,b_{x,\{x,v\}}} \cap D_{\{u,v\}}| \right) \\
      &\le \frac{4 C}{s^2} \cdot 2 \frac{\Delta s^2}{C^2} \frac{3 s^2}{2 C} = 12 \frac{\Delta}{C} \frac{s^2}{C} < \frac{s^2}{8 C} & \text{since $\Delta \le C / 128$}
  \end{align*}

By the multiplicative/Chernoff-like formulation of Azuma's inequality,
  \begin{align*}
    \Pr&\left[\sum_{x \in M_{u,v}} W_{x,u} + \sum_{x \in M_{v,u}} W_{x,v} \ge \frac{s^2}{4 C}\right] \\
      &\le \exp( -\frac{1}{3} \frac{s^2}{4 C}) \le \exp\left( - \frac{32}{3} \log\frac{n}{\delta} \right) \le \frac{\delta}{2 n^2}
  \end{align*}
  By a union bound over all edges, the probability that any edge $\{u,v\}$ has $|F_u \cap F_v| \le \frac{s^2}{4 C}$ is $\le \delta / 2$.

The permutations $(\sigma_v)_{v\in V}$ satisfy property U if:
  \begin{itemize}
    \item For all pairs $(u,i),(v,j) \in V \times [C/s]$, with $u \ne v$, we have $|P_{u,i} \cap P_{v,i}| \ge \frac{s^2}{2 C}$.
    \item For each $(u,i) \in V \times [C/s]$, $S \subseteq (V \setminus \{s\}) \times [C/s]$ where $|S| \le s \Delta / C$ and $S$ includes no two vertices $(v,i),(u,j)$ with $v = u$, and all $T \in \binom{P_{u,i}}{|S| - 1}$, there exists some $(x,j) \in S$ for which $|P_{x,j} \cap T| < \frac{1}{10} |P_{x,j} \cap P_{u,i}|$. (This is, in effect, a stronger version of Hall's condition).
  \end{itemize}

For the first part of property $U$, it is straightforward to bound the probability that it does not hold. For a given pair $(u,i),(v,j) \in V \times [C/s]$, $u\ne v$, because the permutations are $(\epsilon,s)$-wise independent, the sets $P_{u,i}$ and $P_{v,j}$ are within $\epsilon$-total-variation distance of being uniformly random subsets of $[C]$ of size $s$, we can apply a Chernoff bound for the number of elements in $P_{u,i}$ that lie in $P_{v,j}$:
  \begin{align}
    \Pr[ P_{u,i} \cap P_{v,j} \le \frac{1}{2} \frac{s^2}{C} ] \le \exp( -\frac{1}{8}  \frac{s^2}{C} ) + \epsilon \le \exp( - 2^{10} \log (n/\delta)) + \epsilon \le \frac{\delta}{2 n^2} \end{align}
  (The additive factor $\epsilon$ accounts for the maximum difference in probabilities for this event between the case where $P_{u,i}$ is exactly uniform and the case where it is $\epsilon$-far from such.)

For the second part, consider a specific combination $(u,i,S,T)$, and fix $P_{u,i}$. Then the probability that this combination violates property U is:
  \begin{align}
    \Pr\left[ \bigwedge_{(x,j) \in S} \left\{ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i}\right\} \right] \le \prod_{(x,j) \in S} \Pr_{P_{x,j}}\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} | \right] \end{align}
  since the $P_{x,j} \in S$ are all independent, since $S$ contains at most one entry for each $v \in V$. Since $P_{x,j}$ is a uniformly random subset $[C]$,
  $P_{x,j} \cap P_{u,i}$ is symmetrically distributed over $P_{u,i}$. Now let $\hat{T}$ be a uniformly random element of $\binom{P_{u,i}}{s}$, and define indicator random variables $\{Y_k\}_{k \in P_{u,i}}$ so that $Y_k = 1$ iff $k \in \hat{T}$; these are negatively associated and $\mathbb{E}[Y_k] = \frac{|S| - 1}{s}$. Thus, if we assume $|P_{x,j} \cap P_{u,i}| = h$:
  \begin{align*}
    \Pr_{P_{x,j}}&\left[ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i} |  \Big| |P_{x,j} \cap P_{u,i}| = h\right] \\
      &\le \Pr_{\hat{T}}\left[ |P_{x,j} \cap \hat{T}| \ge \frac{1}{10} h \Big| |P_{x,j} \cap P_{u,i}| = h \right] + \epsilon \\
      &= \Pr_{\{Y_k\}_{k \in P_{u,i}}}\left[ \sum_{k \in P_{u,i}} Y_k \ge \frac{1}{10} h \Big| |P_{x,j} \cap P_{u,i}| = h | \right] + \epsilon \\
      &\le \exp\left( -2 \left(\frac{1}{10} - \frac{|S| - 1}{s} \right)^2 h \right) + \epsilon \\
      &\le \exp\left( -2 \left(\frac{1}{10} - \frac{\Delta}{C} \right)^2 h \right) + \epsilon \le \exp\left( - h / 200 \right) + \epsilon  \qquad \text{since $C = 32 \Delta$}
  \end{align*}

Substituting this result into Eq. \ref{eq:superhall-specific} gives:
  \begin{align*}
    \Pr\left[ \bigwedge_{(x,j) \in S} \left\{ |P_{x,j} \cap T| \ge \frac{1}{10} |P_{x,j} \cap P_{u,i}\right\} \right] \le 2^{|S|} \exp\left( - |S| \frac{s^2}{400C} \right) \,.
  \end{align*}
  Taking a union bound over all $(u,i,S,T)$ tuples gives:
  \begin{align*}
    \Pr&[\text{second part of Property U fails}] \\
      &\le \sum_{(u,i) \in V \times [C/s]} \sum_{k=1}^{s \Delta / C} \sum_{\text{valid $S$ with $|S| = k$}} \sum_{T \subseteq \binom{P_{u,i}}{k-1}} 2^{k} \exp\left( - k \frac{s^2}{400C}\right) \\
      &\le n \cdot \sum_{k=1}^{s \Delta / C} \cdot \binom{n - 1}{k} \left(\frac{C}{s}\right)^k \cdot \binom{s}{k - 1} \cdot 2^{k} \exp\left( - k \frac{s^2}{400C}\right) \\
      &\le n \sum_{k=1}^{s \Delta / C} \left( 2 n C s \exp\left(- \frac{s^2}{400 C}\right) \right)^k \\
      &\le 2 n \cdot 2 n C s \exp\left(- \frac{s^2}{400 C}\right) \qquad\qquad \text{for large enough $s^2/C$} \\
      & \le 4 n^2 \cdot (32 n)^2 \exp(- \frac{2048}{100} \log(n/\delta)) \le \frac{\delta}{2} \qquad\qquad \text{since $s \le C = 32 \Delta$}
  \end{align*}

Invariant W automatically holds when $t = 0$, since no edges have been colored. Say the invariant holds at time $t - 1$. Then we are guaranteed that $|U_{t-1,z,v_t}| \le \frac{1}{3} |P_z \cap P_{v_t}|$ for all $z \in A(v_t)$, and want to find color assignments for the edges from $A(v_t)$ to $z$ so that $|U_{t,z,v_t}| \le \frac{1}{3} |P_z \cap P_{v_t}|$ for all $z \in B(v_t)$. To do this, we will first pick a set $F \subseteq P_{v_t}$ that satisfies:
  \begin{align}
    \forall x \in A(v_t):&\quad |P_x \cap P_{v_t} \setminus U_{t-1,x,v_t} \setminus F| \ge \frac{1}{10} |P_x \cap P_{v_t}| \\
    \forall x \in B(v_t):&\quad |(P_y \cap P_{v_t}) \setminus F| \le \frac{1}{3} |P_y \cap P_{v_t}| \end{align}

That such a set $F$ exists follows by the probabilistic method; say $F$ were chosen so that each element of $P_{v_t}$ is included u.a.r with probability $\frac{7}{10}$. For $i \in P_{v,t}$, let $X_i$ be the indicator random variable for the event that $i \in F$. Then the probability of Eq. \ref{eq:F-backward} is bounded by:
  \begin{align*}
    \Pr&\left[ |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F| \ge \frac{1}{10} |P_x \cap P_{v_t}| \right] \\
      &\le   \Pr\left[ |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F|      \ge \frac{3}{20} |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}| \right] \quad \text{ since $|(P_x \cap P_{v_t}) \setminus U_{x,v}| \ge \frac{2}{3} |P_x \cap  P_{v_t}|$ } \\
      &\le \Pr\left[ \sum_{i \in (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}} X_i \ge \frac{17}{20} |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}| \right] \\
      &\le \exp\left(- \frac{9}{200} |P_x \cap P_{v_t} \setminus U_{t-1,x,v_t}| \right) \qquad \text{by Chernoff bound, since $\mathbb{E}$ of LHS is $\frac{14}{20} |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}|$} \\
      &\le \exp\left(- \frac{3}{100} |P_x \cap P_{v_t}| \right) \qquad \text{since $|(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t}| \ge \frac{2}{3} |P_x \cap P_{v_t}|$} \\
      & \le \exp\left(-\frac{3 s^2}{200 C}\right) = \exp\left(- \frac{3072}{25} \log(n/\delta)\right) < \frac{1}{2 n}
  \end{align*}
  And for Eq. \ref{eq:F-forward}:
  \begin{align*}
    \Pr\left[ |(P_x \cap P_{v_t}) \setminus F| \ge \frac{1}{3} |P_x \cap P_{v_t}| \right] 
      &= \Pr\left[ \sum_{i \in (P_x \cap P_{v_t})} X_i \le \frac{2}{3} |P_x \cap P_{v,t}| \right] \\
      &\le \exp\left( -2 \left(\frac{7}{10} - \frac{2}{3}\right)^2 |P_x \cap P_{v,t}| \right) \\
      &\le \exp\left(-\frac{1}{450} |P_y \cap P_v|\right) = \exp\left(-\frac{s^2}{900 C}\right) = \exp\left(- \frac{2048}{225} \log(n/\delta)\right) < \frac{1}{2n}
  \end{align*}
  Applying a union bound for the complements of Eq. \ref{eq:F-forward} and Eq. \ref{eq:F-backward} over all applicable $z$, we find that both conditions hold with positive probability, so a suitable $F$ exists.

To prove there exists a matching $M$ in $J$, we verify that Hall's condition holds. For any subset $S$ of the vertices in $A(v_t)$, we want to show that
  \begin{align*}
    \left| \bigcup_{x \in S} ((P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F) \right| \ge |S|
  \end{align*}
  The construction of $H$ ensures that $A(v_t)$ and all subsets thereof satisfy the conditions for the second part of Property U (Specifically, $|A(v_t)| \le s \Delta / C$, and that for any $b \in V$ there is at most one $j$ for which $(b,j) \in A(v,t)$.) By this property, we are guaranteed that for all $T \subseteq P_{v_t}$ of size $k-1$, that there exists some $x \in S$ for which $|P_x \cap T| \le \frac{1}{10} |P_x \cap P_{v_t}$. If Hall's condition does not hold for $S$, then there must exist some $T \subseteq P_{v,t}$ for which:
  \begin{align*}
  &\bigcup_{x \in S} ((P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F) \subseteq T \\
  \implies \quad \forall x \in S:\quad & (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F \subseteq T \\
  \implies \quad \forall x \in S:\quad & (P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F \subseteq T \cap P_x \\
  \implies \quad \forall x \in S:\quad & |(P_x \cap P_{v_t}) \setminus U_{t-1,x,v_t} \setminus F| \le |T \cap P_x| \\
  \implies \quad \forall x \in S: \quad& \frac{1}{10} |P_x \cap P_{v_t}| \le |T \cap P_x| \qquad \text{by Eq. \ref{eq:F-backward}}
  \end{align*}

Let $H$ be the simple graph on $V \times [C/s]$ formed
  by mapping each edge $\{x,y\}$ arriving in the input stream at time $t$ to the edge $\{(x,b_{x,t}),(y,b_{y,t})\}$. Because the stream satisfies Property Z, for any $u,i,v$, there is at most one $j$ for which $\{(u,i),(v,j)\}$ is in $H$. Thus, by \Cref{lem:offline-ea-coloring}, with probability $\ge 1 - \delta$ over randomly chosen advice, the permutations $(\sigma_v)_{v \in V}$ are good, and there exists an edge coloring $\chi$ of $H$ where each edge $\{(x,i),(y,j)\}$ is given a color  from $P_{x,i} \cap P_{y,j}$. This implies that, \emph{if}
  the color chosen at Line \ref{step:layer-color-choice} were to exactly match the color from $\chi$ at each step, it would be possible to for the first layer to assign a color to every edge.

Thus, at the end of the stream, there will be no "good" edges remaining;
  and since the number of "good" edges is reduced by at most 3 per edge that was
  colored, the number of colored edges must be at least $|E|/3$.

\Cref{alg:det-ea-edgecol} runs $O(\log \Delta)$ instances of an inner algorithm, \Cref{alg:det-ea-inner}, which is designed to give correct edge colorings
  for graph streams with a specific low-repetition guarantee: that for any vertex $v \in V$, if one considers the sequence of edges adjacent to $v$ in stream order,
  and splits them into $O(\sqrt{\Delta / \log n})$ contiguous lists, that no lists
  will include a given edge more than once. To handle edges that are more
  commonly repeated, \Cref{alg:det-ea-edgecol} will keep track of all edges which,
  if added, might violate the guarantee, and send them to another instance of
  \Cref{alg:det-ea-inner} which handles graph streams where no contiguous lists
  of edges adjacent to a vertex includes a given edge twice; and if an edge
  in the stream might violate that condition, the algorithm sends it to another
  copy of \Cref{alg:det-ea-inner}, and so on.




  \begin{algorithm}[ht!]
    \caption{Inner algorithm:  $O(\Delta \log \Delta)$ edge coloring for graph edge arrival streams which have certain substreams satisfying Property Z, plus reference counting }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of edge arrivals $n$-vertex graph $G=(V,E)$. 
      \Statex Assume $\Delta$ is a power of two
      \Statex Superscript $\cdot^{(\ell)}$ indicates \emph{level} of algorithm

      \Statex
      \Statex \underline{\textbf{Initialize($\ell$, $\Delta^{(\ell)}$, $R$)}:}
        \Statex Input $\Delta^{(\ell)}$ is the maximum degree of the input graph
        \Statex Let $C^{(\ell)} = 32 \Delta^{(\ell)}$
        \State $D^{(\ell)} \gets \emptyset$ be a set of $O(n \log n)$ "overflow" edges 

        \If{ $\Delta^{(\ell)} \ge 256 \log(n/\delta))$}
          \Comment{Condition for \Cref{lem:offline-ea-coloring} to apply}
          \State Let $s^{(\ell)}$ satisfy constraints of \Cref{lem:offline-ea-coloring}
          \State Advice: $\{\sigma_v^{(\ell)}\}_{v \in V}$ are permutations over $[C^{(\ell)}]$, "good" for \Cref{lem:offline-ea-coloring}

          \For{each \emph{layer} $\xi \in [\ceil{\log_{3/2}{\Delta^{(\ell)}}}]$}
            \State $\mathfrak{I}^{(\ell,\xi)} \gets$ \textsc{Initialize}($\ell$,$\xi$,$\Delta$,$C$,$s$,$\{\sigma_v^{(\ell)}\}_{v\in V}$,$R$) from \Cref{alg:det-ea-partial}
          \EndFor
        \EndIf

    \Statex 
    \Statex\underline{\textbf{Process}(edge $\{x,y\}$) $\rightarrow$ \textbf{color} $\in \left[\ceil{\log_{3/2}{\Delta^{(\ell)}}}\right] \times \left[C^{(\ell)}\right]$}
        \If{$\Delta^{(\ell)} \ge 256 \log(n/\delta))$}
          \For{$\xi \in \left[\ceil{\log_{3/2}{\Delta^{(\ell)}}}\right]$} \State Let $c \gets \mathfrak{I}^{(\ell,\xi)}.\textsc{Process}(\{x,y\})$ from \Cref{alg:det-ea-partial}
            \If{$c \ne \bot$}
              \State \textbf{return} color $(\xi, c)$
            \EndIf
          \EndFor
        \EndIf
        \State $D^{(\ell)} \gets D^{(\ell)} \cup \{\{x,y\}\}$ \State Increase reference count for $\{x,y\}$ in $R$
        \State Greedily pick a color class $c \in [C^{(\ell)}]$ not used by any edge in $D^{(\ell)}$ adjacent to $x$ or $y$
        \State $\chi^{(\ell)}_{\{x,y\}} \gets (0,c)$
        \State $M^{(\ell)}_{\{x,y\}} \gets 1$
        \State \textbf{return} color $(0,  c)$
    \end{algorithmic}
  \end{algorithm}

In \Cref{alg:det-ea-inner}, the for loop at Line \ref{step:loop-over-layers} sends the edge $\{x,y\}$ being processed to each of the $\ceil{\log_{3/2} \Delta^{(\ell)}}$ instances of \Cref{alg:det-ea-partial}, until either one of them assigns a color to the edge, or all the instances fail to color the edge. Since each instance is guaranteed to color a $\ge 1/3$ fraction of the edges it processes, only a $(2/3)^\ceil{\log_{3/2} \Delta^{(\ell)}} \le \frac{1}{\Delta^{(\ell)}}$ fraction of the edges received by \Cref{alg:det-ea-inner} will reach Line \ref{step:record-unpartialcolored-edge} of the algorithm and be stored in $D^{(\ell)}$; since there are only $O(n)$ such edges, storing them does not significantly affect the space usage of the algorithm. These edges will be greedily colored using a fresh set of colors.

  \begin{algorithm}[ht!]
    \caption{Deterministic algorithm for $O(\Delta (\log \Delta)^2)$ edge coloring for multigraph edge arrival streams }
    \begin{algorithmic}[1]
    \Statex \textbf{Input}: Stream of edge arrivals $n$-vertex graph $G=(V,E)$
      \Statex Assume $\Delta$ is a power of two
      \Statex
      \Statex \underline{\textbf{Initialize}:}

      \State Let $R \gets \emptyset$ be a reference counted pool of edges. (This will be a set of "recent" edges for each layer in each level, including edges that are either in $D^{(\ell)}$ or have a reference from one of the $F_x^{(\ell,\xi)}$
      \State Each edge $e \in R$ will have, per level $\ell$, one associated counter $M^{(\ell)}_{e} \in [0, 2^\ell]$ and color class $\chi^{(\ell)}_{e} \in \{0,\ldots,\ceil{\log_{3/2}{\Delta^{(\ell)}}}\} \times [C^{(\ell)}]$. When an edge is added to the pool, $M^{(\ell)}_{e} = 0$ for all layers.

      \For{each \emph{level} $\ell$ in $0,\ldots,\log \Delta$}
        \State Define $\Delta^{(\ell)} = \Delta / 2^\ell$
        \State $\mathfrak{K}^{(\ell)} \gets$ \textsc{Initialize}($\ell$,$\Delta^{(\ell)}$) from \Cref{alg:det-ea-inner}
      \EndFor

    \Statex 
    \Statex\underline{\textbf{Process}(edge $\{x,y\}$) $\rightarrow$ \textbf{color}}

      \For{$\ell$ in $0,\ldots,\log \Delta$} \If{$\{x,y\}$ is in $R$ and $M^{(\ell)}_{\{x,y\}} > 0$}
          \If{$M^{(\ell)}_{\{x,y\}} = 2^\ell$}
            \State \textbf{continue} \Else
            \State $M^{(\ell)}_{\{x,y\}} \gets M^{(\ell)}_{\{x,y\}} + 1$
            \State Let $(i,j) \gets \chi^{(\ell)}_{\{x,y\}}$
            \State \textbf{return} color $\left(\ell, i,  (j - 1) 2^\ell + M^{(\ell)}_{\{x,y\}}\right)$
          \EndIf
        \Else
          \State Let $(\xi, c) \gets \mathfrak{K}^{(\ell)}.\textsc{Process}$($\{x,y\}$) for level $\ell$ algorithm
          \State \textbf{return} color $\left(\ell, \xi,  (c - 1) 2^\ell + 1\right)$
        \EndIf
      \EndFor
    \end{algorithmic}
  \end{algorithm}

For each $i \in \floor{n/\Delta}$, let $C_i$ be the event that there is a $P_i$-saturating
  matching in the bipartite graph between $P_i$ and $[C]$, where each $v \in P$ is adjacent to all $c \in S_v$. Let $\gamma = 2 - \beta$. Then we have:
  \begin{align}
    p(n, \Delta, \beta) \le \prod_{i = 1}^{\ceil{\frac{1}{2} \gamma n / \Delta}} \Pr[C_i | C_1,\ldots,C_{i-1}] \end{align}
  We will prove Eq. \ref{eq:rgmprob} by proving a upper bounds on $\Pr[C_i | C_1,\ldots,C_{i-1}]$, for all $i \in [\ceil{\frac{1}{2} \gamma n / \Delta}]$, and then applying Eq. \ref{eq:strat-pndb-ub}.

By Markov's inequality, the fraction of vertices in $B$ for which $|S_v| - 1 \ge 1$ is $\le \beta - 1 = 1 - \gamma$, so $\Pr_{v \sim B}[|S_v| = 1] \ge \gamma$. For each $i \in [\floor{n/\Delta}]$, let $T_i = B \setminus \bigcup_{j < i} P_j$. Then for all $i \le \ceil{\frac{1}{2} \gamma n / \Delta}$:
  \begin{align*}
    \frac{|\{v \in T_i : |S_v| = 1\}|}{|T_i|} \ge \frac{|\{v \in B : |S_v| = 1\}| - \Delta (i-1)}{|B| - \Delta i} \ge \frac{\gamma n - (i-1) \Delta}{n - \Delta (i-1)} \ge \frac{\gamma n - \frac{1}{2} \gamma n}{n - \frac{1}{2} \gamma n} \ge \frac{1}{2} \gamma
  \end{align*}
  Consequently, conditioned on $P_1,\ldots,P_{i-1}$, the set $P_i$ will be drawn uniformly at random from a set $T_i$ of vertices for which at least a $\gamma / 2$ fraction have singleton color sets (have $|S_v| = 1$).

For each $j \in T_i$, let $X_j$ be the indicator random variable for the event that $j \in P_i$. For each $k \in [C]$, let $Y_k = \sum_{j \in L_k} X_j$. Since the random variables $\{X_j\}_{j \in T_i}$ are negatively associated, sums of disjoint sets of them, the $\{Y_k\}_{k \in [C]}$, are also negatively associated. (See \cite{JoagDevP83}.) We have:
  \begin{align*}
    \Pr&[P_i \text{ has no two elements from same $L_k$}] \\
      &\le \Pr[\bigwedge_{k \in [C]} \{ Y_k \le 1 \} ] \\
      &\le \prod_{k \in [C]} \Pr[Y_k \le 1] \qquad \text{since negative association $\implies$ negative orthant dependence}
  \end{align*}

Having bounded $\Pr[Y_k \le 1]$, it follows that:
  \begin{align*}
    p(n, \Delta, \beta) &\le \prod_{i = 1}^{\ceil{\frac{1}{2} \gamma n / \Delta}} \Pr[C_i | C_1,\ldots,C_{i-1}] \le \left( \exp\left(- \gamma^2 / 2^{12}\right)^C \right)^{\ceil{\frac{1}{2} \gamma n / \Delta}} \\
      &\le  \exp\left(- \gamma^2 / 2^{12} \cdot C \cdot \ceil{\frac{1}{2} \gamma n / \Delta} \right) \le \exp(-\gamma^3 n / 2^{13})
  \end{align*}

We conclude:
  \begin{align*}
    S \ge \log \frac{1}{p(n, \Delta, \beta)} = \Omega((2-\beta)^3 n)
  \end{align*}

First,
  \begin{align*}
    \mathbb{E}[W] = \sum_{k=0}^{\infty} \Pr[W \ge k] \le \sum_{k=0} 1/2^{k + 1} = 1
  \end{align*}

Next,
  \begin{align*}
    \mathbb{E}[e^{t W}] &= \sum_{k=0}^{\infty} e^{t k} \Pr[W = k] \le \sum_{k=0}^{\infty} e^{t k} \frac{1}{2^{k+1}} = \frac{1}{2} \sum_{k=0}^{\infty} \left(\frac{e^t}{2}\right)^k = \frac{1}{2}\cdot\frac{1}{1 - \frac{1}{2}e^t} = \frac{1}{2 - e^t}
  \end{align*}

If $\pi$ is a uniformly random permutation on $[C]$, then for all lists of distinct $h_1,\ldots,h_s$, and all lists of distinct $j_1,\ldots,j_s$, we have
  \begin{align*}
    \Pr[\bigwedge_{i\in[s]} \pi(h_i) = j_i] = \frac{1}{\prod_{i \in [s]} (C - i + 1)}
  \end{align*}

Now, let $f : \{0,1\}^{k C/2} \times [C] \mapsto [C]^k$ be the function which maps the gate-controlling vector $x \in \{0,1\}^{k C / 2}$ and an input $a \in [C]$ to the path $b_1,\ldots,b_k$ that $a$ takes through the switching network $\mathcal{N}$ if its gates are configured according to $x$. The last node of this path, $f(x, a)_k$ is the output of $\mathcal{N}$ given $x$ and $a$. Each path $P = (a,b_1,\ldots,b_k)$ through the switching network corresponds to a restriction $R_P \in \{0,1,\star\}^{k C / 2}$ which has value $\star$ on gates not touched by the path, and for each gate traversed by the path assigns either $0$ or $1$ depending on whether a straight or switched configuration of the gate is compatible with $P$. Since all paths through the network have length $k$, $R_P$ only sets $k$ coordinates. Now, for each pair $(a,b) \in [C]^2$, let 
  \begin{align*}
    \mathcal{F}_{a,b} = \{R_P : P = (a,b_1,\ldots,b_{k-1},b) \text{ is a possible path}\}
  \end{align*}

Then, for lists $(h_1,\ldots,h_s)$, $(j_1,\ldots,j_s)$, define 
  \begin{align*}
    \mathcal{K}_{h_1,\ldots,h_s,j_1,\ldots,j_s} = \{ R \in \{0,1,\star\}^{k C / 2} : \forall i \in [k], \exists T \in \mathcal{F}_{h_i,j_i} \text{where $R$ is a minimal refinement of $T$}  \}\,,
  \end{align*}
  i.e., the set of minimal restrictions for vectors in $\{0,1\}^{k C / 2}$ which
  completely determine the paths through the switching network of inputs $(h_1,\ldots,h_s)$.

Thus,
  \begin{align*}
      &\frac{1}{2} \sum_{\text{distinct $b_1,\ldots,b_k$ in $[C]$,}} \left| \Pr\left[\bigwedge_{i \in [s]} \{ f(X, h_i)_k = j_i \} \right] - \frac{1}{\prod_{i \in [s]} (C - i + 1)} \right| = \\
      &\frac{1}{2} \sum_{\text{distinct $b_1,\ldots,b_k$ in $[C]$,}} \left| \Pr\left[\bigwedge_{i \in [s]} \{ f(Y, h_i)_k = j_i \} \right] - \frac{1}{\prod_{i \in [s]} (C - i + 1)} \right| \le \epsilon
  \end{align*}
  which proves that the switching network evaluated on $X$ produces outputs that are $(\epsilon,s)$-wise independent.

